import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-d2-001","clusterId":"D","werkstueckRef":"D.3.3","stufe":1,"question":"Wie ist das Verhalten des Teamleiters einzuordnen, und woran erkennst du es?","options":["Er stellt systematisch ihre Erinnerung und Wahrnehmung infrage, bis sie an sich selbst zweifelt. Das ist ein Angriff auf ihre Fähigkeit zu wissen, was wahr ist.","Er lügt in einem einzelnen Streit, um sich einen Vorteil zu verschaffen. Dass sie dadurch an sich zweifelt, ist nur ein Zufall.","Er schüchtert sie mit Lautstärke und Drohungen ein, bis sie aus Angst nicht mehr widerspricht. Das ist ein Angriff auf ihren Mut, nicht auf ihre Wahrnehmung.","Er macht ihre Gefühle zum eigentlichen Thema und geht auf ihre sachlichen Einwände gar nicht mehr ein. Das ist ein Ablenkungsmanöver ohne Wirkung auf ihre Selbstsicherheit."],"correctIndex":0,"explanation":"Entscheidend ist das Muster, nicht die einzelne Lüge: Er leugnet Geschehenes, bestreitet ihre Erinnerung („Du erinnerst dich falsch“) und wertet ihre Einschätzung ab („überempfindlich“), und das wiederholt über Wochen. Die Folgen passen dazu: Sie zweifelt an sich selbst, fragt andere, ob sie sich alles einbildet, und entschuldigt sich ständig. Das nennt man Gaslighting, nach dem Theaterstück „Gas Light“ (1938), in dem ein Ehemann seiner Frau einredet, sie bilde sich das schwächer werdende Gaslicht nur ein. Eine einzelne Lüge im Streit zielt auf einen Vorteil, Einschüchterung auf Angst, Gefühlsabwertung auf Ablenkung; Gaslighting zielt darauf, dass jemand der eigenen Wahrnehmung nicht mehr traut. Schriftliche Notizen helfen dagegen, weil sie sich nicht wegleugnen lassen.","coreRule":"⚡ Gaslighting ist nicht eine Lüge, sondern ein System: Es zielt darauf, dass du deiner eigenen Wahrnehmung nicht mehr traust.","beleg":"Werkstück D.3.3 (Kernidee, Kontext & Tiefe); Fn. gl-d-gaslight (Hamilton, „Gas Light“, Uraufführung 5. Dezember 1938, Richmond Theatre; MGM-Verfilmung 1944)","status":"entwurf","scenario":"Ein Teamleiter sagt im Meeting: „Das habe ich nie gesagt.“ Eine Mitarbeiterin hat die Zusage am Vortag schriftlich notiert und widerspricht. Er antwortet: „Du erinnerst dich falsch. Du bist in letzter Zeit ohnehin überempfindlich.“ Das passiert seit Wochen immer wieder. Inzwischen fragt sie Kollegen, ob sie sich wohl alles nur einbildet, und entschuldigt sich ständig bei ihm.","quote":"","quoteLabel":"","kurz":"Entscheidend ist das Muster über Wochen: Er leugnet Geschehenes, bestreitet ihre Erinnerung und wertet sie als „überempfindlich“ ab. Zum Gaslighting passt ihr Selbstzweifel, während eine einzelne Lüge nur auf einen Vorteil zielt.","prueffrage":"Was hat die Mitarbeiterin schriftlich, was entgegnet er darauf, und wie oft geht das schon so?","rueckmeldung":[{"option":1,"text":"Dass er hier lügt, stimmt. Ein einzelner Streit mit einem Vorteil als Ziel erklärt aber nicht, warum es seit Wochen immer wieder geschieht, und ihre wachsenden Selbstzweifel sind eher die passende Folge als ein Zufall."},{"option":2,"text":"Einschüchterung würde Angst erzeugen. Von Lautstärke oder Drohungen ist aber nirgends die Rede, und sie widerspricht ihm zunächst sogar. Was bei ihr wächst, ist Zweifel an der eigenen Wahrnehmung, nicht Furcht."},{"option":3,"text":"„Überempfindlich“ betrifft zwar ihr Empfinden, doch er geht auf den sachlichen Einwand ein, indem er ihre Erinnerung bestreitet. Und dass sie sich ständig entschuldigt und Kollegen fragt, ob sie sich alles einbildet, spricht gegen „ohne Wirkung“."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2"},{"id":"qx-d2-002","clusterId":"D","werkstueckRef":"D.3.3","stufe":2,"question":"Welcher Schritt hilft dir am besten, wieder festen Boden unter den Füßen zu bekommen?","scenario":"Eine Kollegin sagt dir immer wieder: „So war das nie“, „Du erinnerst dich falsch“, „Du bist gerade so empfindlich“. Du merkst, dass du dir selbst nicht mehr sicher bist, ob deine Erinnerung an die Gespräche stimmt.","options":["Du übernimmst vorerst die Version der Kollegin, um Streit zu vermeiden, und klärst später, wer recht hatte.","Du hältst Gespräche und Ereignisse zeitnah schriftlich fest, damit du später auf etwas Überprüfbares zurückgreifst.","Du fragst Bekannte, welche Version glaubwürdiger klingt, und schließt dich der Mehrheitsmeinung an.","Du gehst die Gespräche in Gedanken immer wieder durch, damit deine Erinnerung klar bleibt."],"correctIndex":1,"explanation":"Wenn jemand systematisch bestreitet, was du erlebt hast, steht Aussage gegen Aussage, und deine eigene Wahrnehmung wirkt zunehmend unsicher. Ein geschriebenes Protokoll ist eine Waffe gegen das Leugnen der Vergangenheit: Mit Notizen zu Gesprächen und Ereignissen kannst du nachlesen, was war, statt nur im Kopf zu grübeln. Die Version der anderen vorab zu übernehmen, würde den Zweifel nur verfestigen. Und wenn Bekannte abstimmen, welche Version „glaubwürdiger klingt\\", entscheidet Sympathie oder Mehrheit statt Beleg: Sie waren nicht dabei und können nichts überprüfen. Hilfreich ist die Frage: Was habe ich selbst gesehen und gehört?","coreRule":"⚡ Schreib auf, was geschieht: Ein Protokoll lässt sich nicht wegleugnen.","quote":"","quoteLabel":"","beleg":"Werkstück D.3.3 (Anti-Denkmuster, Aktivierungs-Frage und Logbuch)","status":"entwurf","kurz":"Wenn jemand systematisch bestreitet, was du erlebt hast, hilft dir etwas, das du nachlesen kannst. Zeitnahe Notizen geben dir Überprüfbares, wo sonst Aussage gegen Aussage steht und du nur im Kopf grübelst.","prueffrage":"Worauf stützt sich bisher deine Erinnerung an die Gespräche, und worauf die Version der Kollegin?","rueckmeldung":[{"option":0,"text":"Die Version der Kollegin vorerst zu übernehmen, spart Streit, nährt aber genau den Zweifel, der dich verunsichert. Später lässt sich ohne Belege auch nicht klären, wer recht hatte."},{"option":2,"text":"Eine Außensicht kann entlasten, doch Bekannte waren bei den Gesprächen nicht dabei und können nichts überprüfen. Dann entscheiden Sympathie oder Mehrheit, nicht das, was tatsächlich gesagt wurde."},{"option":3,"text":"Gedankliches Wiederholen fühlt sich wie Vergewissern an, bleibt aber im Kopf und liefert nichts Überprüfbares. Gerade wenn du schon zweifelst, kann dich das Grübeln eher noch unsicherer machen."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2"},{"id":"qx-d2-003","clusterId":"D","werkstueckRef":"D.3.3","stufe":3,"question":"Eine Kollegin sagt dir mehrfach hintereinander: „Das habe ich nie gesagt“, obwohl du eine Mail von ihr hast, in der es steht. Als du darauf hinweist, meint sie: „Du bist in letzter Zeit so überempfindlich.“ Eine Bekannte rät dir: „Sei nicht so streng mit ihr. Ein bisschen Leugnen und Umdeuten ist in jedem Konflikt normal und hat auch seine nützliche Seite.“ Was ist an diesem Rat falsch?","options":["Er verkennt, dass solches Verhalten nur dann schadet, wenn die Kollegin es dir gegenüber offen als Angriff formuliert.","Er übersieht, dass Leugnen belegter Tatsachen und Umdeuten der Wahrnehmung als Muster dein Vertrauen in die eigene Erinnerung untergraben und auch in kleinem Maß keine harmlose, nützliche Seite haben.","Er übersieht, dass sich das Verhalten erst dann als schädlich einstufen lässt, wenn es nicht nur dich, sondern mehrere Menschen im Umfeld betrifft.","Er unterschätzt die Rolle der Absicht: Solange die Kollegin nicht nachweislich plant, dich zu verunsichern, bleibt es eine gewöhnliche Meinungsverschiedenheit."],"correctIndex":1,"explanation":"Wer Dinge leugnet, die belegt sind (hier die Mail), und die Wahrnehmung des Gegenübers als „überempfindlich“ abtut, greift dessen Vertrauen in die eigene Erinnerung an; geschieht das wiederholt, spricht man von Gaslighting, nach dem Theaterstück „Gas Light“ von 1938. Dieses Muster hat keine harmlose oder nützliche Seite, denn es läuft darauf hinaus, dass das Gegenüber an der eigenen Wahrnehmung zweifelt, ob es nun bewusst oder unbewusst eingesetzt wird. Es braucht also weder einen nachgewiesenen Plan noch einen offen formulierten Angriff, und es muss auch nicht mehrere Menschen treffen: Der Schaden entsteht schon bei einer einzelnen Person. Der Rat, das als normalen Konflikt hinzunehmen, ist deshalb ein Fehlschluss. Sinnvoller ist es, die eigene Wahrnehmung zu sichern, etwa mit Notizen und Belegen wie der Mail.","coreRule":"⚡ Gaslighting hat keine harmlose Dosis: Wer belegte Tatsachen leugnet und deine Wahrnehmung für unzuverlässig erklärt, schadet von Anfang an, egal ob mit Absicht oder ohne.","beleg":"Werkstück D.3.3 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Wer Belegtes leugnet und die Wahrnehmung des anderen als „überempfindlich“ abtut, untergräbt dessen Vertrauen in die eigene Erinnerung. Der Rat übersieht, dass dieses Muster keine harmlose oder nützliche Seite hat, die man dulden könnte.","prueffrage":"Was steht in der Mail, was sagt die Kollegin dazu, und wie sicher wärst du dir nach dem dritten Mal noch?","rueckmeldung":[{"option":0,"text":"Weil sie nicht offen angreift, wirkt ihr Verhalten harmlos. Der Schaden entsteht aber gerade leise: Für Zweifel an der eigenen Erinnerung braucht es keinen ausgesprochenen Angriff, wiederholtes Leugnen und ein beiläufiges „überempfindlich“ reichen."},{"option":2,"text":"Ein Muster liegt hier schon vor: Sie leugnet mehrfach und wertet deine Wahrnehmung ab. Dass es außerdem mehrere Menschen treffen muss, ist keine Voraussetzung, denn der Schaden entsteht schon bei einer einzelnen Person."},{"option":3,"text":"Absicht scheint der entscheidende Unterschied zu sein, lässt sich von außen aber selten nachweisen. Auch unbewusst eingesetzt untergräbt dieses Verhalten das Vertrauen in die eigene Erinnerung; entscheidend ist die Wirkung, nicht ein belegter Plan."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2"},{"id":"qx-d2-004","clusterId":"D","werkstueckRef":"D.3.3","stufe":4,"question":"Warum ist dieses Vorgehen mehr als bloßes Überzeugen und eine Form von Gaslighting?","scenario":"Eine neue Bekannte nimmt dich zu einem Treffen ihrer Gruppe mit. Dort sagt ein Sprecher zu einem Neuling: „Dein früheres Denken war falsch und gehirngewaschen. Nur wir sagen dir, was wirklich wahr ist.“ Alles von außen, ob von Familie, Wissenschaftlern oder „Systemmedien“, gilt in der Gruppe als Lüge. Ein Mitglied erzählt dir später: „Früher habe ich selbst viel gezweifelt, aber heute weiß ich, dass ich mir nur noch von der Gruppe sagen lassen darf, was stimmt.“","options":["Die Gruppe erklärt sich zur einzigen Quelle der Wahrheit und bringt Mitglieder dazu, ihrem eigenen früheren Urteil zu misstrauen.","Die Gruppe lässt Außenstehende ausführlich zu Wort kommen, bewertet deren Aussagen aber grundsätzlich strenger als die eigenen.","Die Gruppe behauptet, ihre Sicht beruhe auf besseren Belegen, nennt aber keine, sodass die Behauptung unüberprüfbar bleibt.","Die Gruppe wirbt mit großen Versprechen, die sich später als übertrieben herausstellen, und enttäuscht so das Vertrauen der Mitglieder."],"correctIndex":0,"explanation":"Entscheidend ist, was mit dem Urteilsvermögen der Person passiert. Gaslighting zielt darauf ab, dass jemand der eigenen Wahrnehmung, Erinnerung und Urteilskraft nicht mehr traut und nur noch glaubt, was der Manipulator sagt. Hier geschieht genau das: Das frühere Denken wird pauschal als „gehirngewaschen“ entwertet, alles Äußere als Täuschung gebrandmarkt, und die Gruppe setzt sich als einzige Wahrheitsquelle. Das isoliert von Familie, Wissenschaft und Medien und macht abhängig von der Einschätzung der Gruppe. Gute Überzeugungsarbeit würde dagegen Gründe nennen, die man selbst prüfen kann, und das eigene Urteil der Person stärken statt ersetzen. Unbelegte Behauptungen oder übertriebene Versprechen sind für sich genommen andere Fehler und erzeugen noch keinen Zweifel an der eigenen Zurechnungsfähigkeit.","coreRule":"⚡ Wer dir sagt, nur er kenne die Wahrheit und dein früheres Denken sei wertlos, will nicht überzeugen, sondern dein Urteil ersetzen.","beleg":"Werkstück D.3.3 (Anwendung & Relevanz, „In Kulten und Verschwörungsmythen“; Verbindungen)","status":"entwurf","kurz":"Entscheidend ist, was mit dem Urteilsvermögen geschieht: Das frühere Denken gilt pauschal als „gehirngewaschen“, alles Äußere als Lüge, und die Gruppe wird zur einzigen Quelle. Das untergräbt das Vertrauen in das eigene Urteil, statt es zu stärken.","prueffrage":"Bekommst du Gründe genannt, die du selbst nachprüfen kannst, oder nur die Auskunft, wem du glauben darfst?","rueckmeldung":[{"option":1,"text":"Strengere Maßstäbe für Fremdes sind ein verbreiteter Denkfehler. Hier kommen Außenstehende aber gar nicht erst zu Wort, sondern gelten pauschal als Lüge, und entscheidend ist, dass das eigene Urteil des Mitglieds entwertet wird."},{"option":2,"text":"Fehlende Belege sind ein echter Mangel, doch die Gruppe beruft sich nicht einmal auf bessere Belege, sondern nur auf sich selbst. Eine unbelegte Behauptung allein lässt zudem niemanden an der eigenen Urteilskraft zweifeln."},{"option":3,"text":"Übertriebene Versprechen können Vertrauen enttäuschen und sind ein eigener Fehler. Davon ist hier aber nicht die Rede, und eine Enttäuschung allein bringt niemanden dazu, dem eigenen Denken grundsätzlich zu misstrauen."}],"familie":"wahrnehmung-festhalten","fertigkeit":"F2"},{"id":"qx-d2-005","clusterId":"D","werkstueckRef":"D.3.4","stufe":1,"question":"Was ist an dieser Reaktion des Vaters als Gesprächsbeitrag das Hauptproblem?","scenario":"Beim Abendessen erzählst du, was du im Seminar über strukturelle Ursachen von Armut gelernt hast: Bildungschancen, soziale Herkunft, Benachteiligung. Dein Vater winkt ab und sagt in einem Ton, der keine Widerrede zulässt: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“","options":["Er beantwortet eine vielschichtige Frage mit einer endgültig klingenden Allerweltsweisheit und beendet so das Gespräch, ohne auf deine Argumente einzugehen.","Er widerlegt deine Argumente mit einem bewährten Sprichwort, denn gesammelte Lebenserfahrung wiegt schwerer als eine Seminarthese.","Er verlangt von dir den Beweis, dass es strukturelle Armutsursachen gibt, und verschiebt damit die Beweislast auf deine Seite.","Er stellt deine Position verzerrt als Ausrede für Untätigkeit dar und widerlegt dann nur diese zugespitzte Version."],"correctIndex":0,"explanation":"Der Satz klingt weise und endgültig, geht aber auf keines deiner Argumente ein. Er ersetzt die Auseinandersetzung durch eine Formel und signalisiert: Das Thema ist für mich erledigt, und du brauchst auch nicht weiter nachzudenken. Ob das Sprichwort im Kern etwas Wahres trifft, ist dafür unerheblich. Entscheidend ist seine Funktion im Gespräch: Es soll die Diskussion beenden, nicht klären. Eine gute Antwort darauf ist, das Klischee „auszupacken“ und zu fragen, wie die Phrase bei den konkreten Details dieses Problems weiterhilft.","coreRule":"⚡ Ein Satz, der eine Frage beendet, statt sie zu beantworten, ist ein Rollladen und kein Argument.","quote":"Sie hat die komplexe, nuancierte Debatte nicht widerlegt, sondern sie einfach kurzgeschlossen.","quoteLabel":"Merksatz:","beleg":"Werkstück D.3.4 (Das Gespräch am Familientisch; Kernidee)","status":"entwurf","kurz":"Der Satz klingt weise und endgültig, geht aber auf kein einziges Argument ein. Statt zu klären, beendet er das Gespräch. Ob im Sprichwort etwas Wahres steckt, ist dafür unerheblich: Entscheidend ist, was er im Gespräch bewirkt.","prueffrage":"Wie könnte das Gespräch nach diesem Satz sinnvoll weitergehen, und was hat der Vater dafür angeboten?","rueckmeldung":[{"option":1,"text":"Lebenserfahrung kann ein wertvoller Hinweis sein, und Sprichwörter fassen oft Erfahrungen zusammen. Hier wird aber nichts widerlegt: Auf keines deiner Argumente wird eingegangen, und ein Sprichwort ersetzt keinen Beleg."},{"option":2,"text":"Das Muster gibt es, die Beweislast lässt sich geschickt verschieben. Der Vater verlangt hier aber gar keinen Beweis. Er stellt auch keine Gegenfrage, sondern winkt ab und sagt einen einzigen Satz."},{"option":3,"text":"Ein Strohmann gibt die Gegenposition verzerrt wieder, um sie leichter anzugreifen. Dein Vater gibt deine Position aber gar nicht wieder, weder verzerrt noch zugespitzt: Er geht auf sie überhaupt nicht ein."}],"familie":"floskel-entpacken","fertigkeit":"F2"},{"id":"qx-d2-006","clusterId":"D","werkstueckRef":"D.3.4","stufe":2,"question":"Welche Reaktion bringt das Gespräch am besten wieder auf die Sache?","scenario":"Du kritisierst eine angebliche Heilmethode und fragst, welche Belege es für ihre Wirkung gibt. Dein Gegenüber antwortet nur: „Vertraue einfach dem Prozess.“","options":["Mit einem Gegensprichwort wie „Vertrauen ist gut, Kontrolle ist besser“ antworten, damit beide Seiten gleich stark dastehen.","Nachfragen, was diese Phrase im vorliegenden Fall konkret leistet und woran man erkennen würde, dass die Methode wirkt.","Der Person vorwerfen, sie höre nicht zu, weil Anhänger solcher Methoden das grundsätzlich nicht täten.","Das Thema ruhen lassen und nichts mehr einwenden, weil gegen allgemein anerkannte Lebensweisheiten kein Einwand weiterhilft."],"correctIndex":1,"explanation":"„Vertraue einfach dem Prozess“ beantwortet deine Frage nach Belegen nicht, sondern beendet sie. Hilfreich ist, die Phrase auf den konkreten Fall anzuwenden: Was genau soll hier geschehen, und woran würde man merken, dass die Methode wirkt oder nicht wirkt? So wird aus der Floskel wieder eine prüfbare Behauptung. Ein Gegensprichwort bleibt selbst eine Floskel und klärt in der Sache nichts. Der Vorwurf, die Person höre nicht zu, ist eine Pauschalunterstellung über eine ganze Gruppe und greift die Person statt der Sache an. Schweigen lässt die unbelegte Behauptung unhinterfragt stehen.","coreRule":"⚡ Packe die Floskel aus: Frag, was sie im konkreten Fall tatsächlich leistet.","beleg":"Werkstück D.3.4 (Anwendung & Relevanz, Esoterik & New Age: „Vertraue einfach dem Prozess“; Das Anti-Denkmuster, Aktivierungs-Frage)","status":"entwurf","kurz":"„Vertraue dem Prozess“ beantwortet die Belegfrage nicht, sondern beendet sie. Wer fragt, was die Methode hier konkret leisten soll und woran man ihre Wirkung erkennen würde, macht aus der Floskel wieder eine prüfbare Behauptung.","prueffrage":"Was weißt du nach dieser Antwort mehr über die Wirkung der Methode als vorher?","rueckmeldung":[{"option":0,"text":"Ein Gegensprichwort wirkt wie ein fairer Ausgleich, weil beide Seiten gleich dastehen. Es bleibt aber selbst eine Floskel und bringt die Frage nach den Belegen nicht zurück auf den Tisch."},{"option":2,"text":"Dass die Antwort nicht auf deine Frage eingeht, stimmt. Der Vorwurf unterstellt aber einer ganzen Gruppe, nicht zuzuhören, und greift die Person an statt die Sache. Damit wird die Belegfrage eher verdeckt als geklärt."},{"option":3,"text":"Das Thema ruhen zu lassen, vermeidet Streit, lässt die unbelegte Behauptung aber unhinterfragt stehen. Auch ein vertraut klingender Satz verdient eine Nachfrage, wenn er die Frage nach Belegen ersetzt."}],"familie":"floskel-entpacken","fertigkeit":"F2"},{"id":"qx-d2-007","clusterId":"D","werkstueckRef":"D.3.4","stufe":3,"question":"Beim Familienessen spricht eine Studentin über strukturelle Ursachen von Armut. Ihr Vater winkt ab: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“ Worin liegt das eigentliche Problem seiner Reaktion?","options":["Das Sprichwort wird als abschließende Antwort benutzt, ohne auf ihre Argumente einzugehen, und damit wird das Gespräch beendet statt geprüft.","Er benutzt überhaupt ein Sprichwort, denn Redewendungen sind bloße Abkürzungen und gehören nicht in ein sachliches Gespräch.","Das Sprichwort ist sachlich falsch, denn eine wahre Aussage könnte das Nachdenken über ein Thema gar nicht beenden.","Er ist der Vater, und gegenüber Eltern hat man ohnehin keine Chance, mit Argumenten durchzudringen."],"correctIndex":0,"explanation":"Ein Sprichwort zur Illustration ist völlig normal, denn solche Redewendungen sind nützliche Abkürzungen und „kultureller Klebstoff“. Zum Problem wird es, wenn es die Funktion eines Schlussstrichs bekommt: Die Studentin hat strukturelle Ursachen genannt, und der Vater geht auf keine davon ein, sondern erklärt die Debatte mit einer Phrase für beendet. Dabei muss die Phrase weder logisch noch wahr sein, um so zu wirken, denn ihre Kraft liegt in der scheinbaren Endgültigkeit und sozialen Akzeptanz. Entscheidend ist also nicht der Inhalt des Spruchs, sondern was er im Gespräch tut: Er ersetzt die Prüfung der Argumente. Wer ihn auspacken will, fragt, wie genau er auf dieses konkrete Problem passt und was er an den genannten Ursachen ändert.","coreRule":"⚡ Nicht das Sprichwort ist das Problem, sondern seine Verwendung als Fragenkiller: Er ersetzt die Prüfung durch eine Phrase.","beleg":"Werkstück D.3.4 (Das Adaptive Talent; Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Der Vater geht auf keines ihrer Argumente ein, sondern erklärt das Gespräch mit einer Phrase für beendet. Ein Sprichwort an sich ist unproblematisch; zum Fehler wird es, wenn es die Prüfung der Argumente ersetzt.","prueffrage":"Wäre die Reaktion des Vaters weniger problematisch, wenn er denselben Gedanken in eigenen Worten statt als Sprichwort gesagt hätte?","rueckmeldung":[{"option":1,"text":"Redewendungen sind tatsächlich Abkürzungen, aber deshalb nicht fehl am Platz: Zur Illustration sind sie völlig normal und nützlich. Problematisch wird ein Spruch erst, wenn er die Prüfung von Argumenten ersetzt."},{"option":2,"text":"Ob das Sprichwort wahr ist, ist hier gar nicht der Punkt: Auch eine Phrase, die stimmen mag, kann ein Gespräch abwürgen. Entscheidend ist, was sie im Gespräch tut, nämlich die Prüfung der Argumente zu ersetzen."},{"option":3,"text":"Familiäre Rollen können ein Gespräch zwar schwieriger machen, doch „keine Chance“ ist eine Pauschale und nennt kein Denkproblem in seiner Reaktion. Entscheidend ist, was der Spruch im Gespräch bewirkt: Er beendet die Prüfung ihrer Argumente."}],"familie":"floskel-entpacken","fertigkeit":"F2"},{"id":"qx-d2-008","clusterId":"D","werkstueckRef":"D.3.4","stufe":4,"question":"Wie reagierst du am besten auf diesen Gesprächsausgang?","options":["Du merkst, dass der Satz nichts widerlegt hat, und fragst, was er im konkreten Fall erklärt: etwa, wie ein Kind ohne weiterführende Schule vor Ort „schmieden“ soll.","Du merkst, dass der Satz die Frage der Tochter beantwortet hat, und lässt das Thema ruhen, weil weitere Details am Kern der Sache ohnehin nichts ändern würden.","Du merkst, dass ein Sprichwort nie als Argument zählt, und hältst dem Vater entgegen, seine Haltung beruhe auf einer Binsenweisheit und sei darum unzulässig.","Du merkst, dass die Tochter ihre Sicht nicht belegt hat, und verlangst, dass sie zuerst alle Studien nennt, bevor ihr Argument überhaupt eine Antwort verdient."],"correctIndex":0,"explanation":"Der Satz wirkt endgültig, widerlegt aber nichts: Er ersetzt die Auseinandersetzung mit den genannten Faktoren durch eine allgemeine Formel. Solche Phrasen beenden das Nachdenken, statt es voranzubringen. Sinnvoll ist deshalb, die Formel auf den konkreten Fall anzuwenden und zu prüfen, was sie dort tatsächlich erklärt. So wird die Diskussion wieder auf die Sachebene gezwungen. Das Sprichwort pauschal als unzulässig abzutun oder von der Tochter zuerst Belege zu verlangen, ersetzt die Phrase nur durch einen anderen Gesprächsabbruch. Hinzunehmen, das Thema sei „erledigt“, bestätigt den Abbruch.","coreRule":"⚡ Eine Phrase, die eine komplexe Frage beendet statt beantwortet, prüfst du, indem du sie auf den konkreten Fall anwendest.","beleg":"Werkstück D.3.4 (Kontext & Tiefe); Fn. gl-d-lifton (Lifton 1961/1989, Kap. 22, „Loading the Language“, S. 429)","status":"entwurf","scenario":"Beim Abendessen erzählt eine Studentin ihren Eltern, was sie im Seminar über die Ursachen von Armut gelernt hat: Bildungschancen, familiäre Herkunft, regionale Unterschiede. Ihr Vater winkt ab: „Am Ende ist es doch ganz einfach: Jeder ist seines Glückes Schmied.“ Das Gespräch verstummt.","quote":"","quoteLabel":"","kurz":"Der Satz wirkt endgültig, erklärt aber im konkreten Fall nichts: Er ersetzt die Auseinandersetzung mit Bildung, Herkunft und Region durch eine Formel. Wendest du sie auf einen Einzelfall an, zeigt sich, was sie tatsächlich leistet.","prueffrage":"Woran könntest du erkennen, ob das Schweigen am Tisch Zustimmung bedeutet oder nur ein abgebrochenes Gespräch?","rueckmeldung":[{"option":1,"text":"Nach dem Satz ist es still geworden, beantwortet wurde die Frage der Tochter damit aber nicht. Wer das Thema ruhen lässt, bestätigt den Abbruch, noch bevor geprüft ist, ob die Details etwas ändern."},{"option":2,"text":"Ein Sprichwort ersetzt keine Begründung, kann aber einen Gedanken enthalten, den man prüfen kann. Es pauschal als unzulässige Binsenweisheit abzutun, beendet das Gespräch ein zweites Mal, statt zu klären, was der Satz im konkreten Fall erklärt."},{"option":3,"text":"Ein Beleg klingt nach sauberem Vorgehen. Hier trifft die Forderung aber nur die Tochter, während der Vater nichts belegt hat, und „alle“ Studien sind kaum zu leisten. So wird aus der Sachfrage ein weiterer Abbruch."}],"familie":"floskel-entpacken","fertigkeit":"F2"},{"id":"qx-d2-009","clusterId":"D","werkstueckRef":"D.3.5","stufe":1,"question":"Wie beurteilst du deine Antwort?","scenario":"Du sagst: „Kein echter Fan unseres Vereins pöbelt im Stadion.“ Dein Freund zeigt dir einen Mann im Vereinstrikot, der Gästefans beschimpft hat. Du antwortest: „Dann ist das eben kein echter Fan.“ Dein Freund fragt: „Woran erkenne ich denn einen echten Fan?“ Du sagst: „Na, daran, dass er nicht pöbelt.“","options":["Du rettest deine Aussage, indem du die Kategorie „Fan“ nachträglich umdefinierst, sodass sie als Tatsachenbehauptung nichts mehr aussagt.","Du hältst an deiner Aussage fest, obwohl ein einzelnes Gegenbeispiel sie nach den Regeln der Beweislast sofort widerlegt hätte.","Du greifst den Mann persönlich an, statt auf die Aussage deines Freundes einzugehen und das Argument sachlich zu prüfen.","Du verallgemeinerst von einem einzigen Fall auf alle Fans, obwohl dein Freund nur diesen einen Mann gezeigt und nichts Allgemeines behauptet hat."],"correctIndex":0,"explanation":"Ursprünglich war deine Aussage überprüfbar: Man hätte einen pöbelnden Fan finden können, um sie zu widerlegen. Mit dem eingeschobenen „echt“ ist sie es nicht mehr. Ein „echter Fan“ ist jetzt per Definition einer, der nicht pöbelt, und die Aussage lautet nur noch: „Wer nicht pöbelt, pöbelt nicht.“ Das stimmt immer und sagt nichts über die Welt. Statt die Behauptung am Gegenbeispiel zu prüfen und womöglich einzuschränken („Die meisten Fans pöbeln nicht“), hast du das Gegenbeispiel aus der Kategorie ausgeschlossen. Das ist die nachträgliche Immunisierung, die als „Kein wahrer Schotte“-Fehlschluss bekannt ist. Die übrigen Antworten treffen nicht zu: Ein Gegenbeispiel widerlegt eine Allaussage durchaus, du ignorierst es aber nur per Umdefinition; einen persönlichen Angriff auf den Mann gibt es nicht; und die Verallgemeinerung stammt von dir, nicht von deinem Freund.","coreRule":"⚡ Wenn ein Gegenbeispiel auftaucht und du die Definition änderst, statt die Behauptung zu prüfen, hast du sie unwiderlegbar und damit inhaltsleer gemacht.","beleg":"Werkstück D.3.5 (Kernidee; Red Flags)","status":"entwurf","kurz":"Mit dem eingeschobenen „echt“ wird aus einer prüfbaren Aussage ein Satz, der immer stimmt: Wer nicht pöbelt, pöbelt nicht. Statt die Behauptung am Gegenbeispiel einzuschränken, schließt du den Mann einfach aus der Kategorie „Fan“ aus.","prueffrage":"Welche Beobachtung im Stadion würde deine Aussage noch widerlegen können?","rueckmeldung":[{"option":1,"text":"Ein einzelnes Gegenbeispiel kann eine Allaussage tatsächlich widerlegen. Du hältst aber nicht stur an ihr fest, sondern entziehst dem Mann die Kategorie „Fan“. So wird die Aussage unwiderlegbar, statt eingeschränkt, etwa auf „die meisten Fans“."},{"option":2,"text":"Einen persönlichen Angriff gibt es hier nicht: Du sprichst dem Mann nicht seine Würde oder Glaubwürdigkeit ab, sondern nur das Etikett „echter Fan“. Das Problem liegt in der Aussage selbst, die du per Umdefinition gegen den Einzelfall abschirmst."},{"option":3,"text":"Verallgemeinert hast du selbst, mit deinem Satz über alle Fans. Dein Freund hat nur einen Einzelfall gezeigt und nichts Allgemeines behauptet. Der Fehler liegt darin, dass du deine Aussage gegen diesen Fall abschirmst, statt sie anzupassen."}],"familie":"definition-nachtraeglich","fertigkeit":"F2"},{"id":"qx-d2-010","clusterId":"D","werkstueckRef":"D.3.5","stufe":2,"question":"Marta behauptet: „Alle Menschen, die sich ernsthaft für Gesundheit interessieren, ernähren sich bewusst.“ Als Tom einen bekannten Gesundheitsberater nennt, der täglich Fast Food isst, antwortet sie: „Dann interessiert er sich eben nicht wirklich für Gesundheit.“ Warum ist Martas Behauptung nach dieser Antwort kaum noch etwas wert?","options":["Mit dem Wort „wirklich“ wird die Tatsachenbehauptung zur bloßen Meinung, die man nicht mehr prüfen muss, solange sie niemanden verletzt oder herabsetzt.","Wer „wirklich“ an Gesundheit interessiert ist, erkennt man jetzt nur noch an der bewussten Ernährung; im Kern heißt die Aussage: „Wer sich bewusst ernährt, ernährt sich bewusst.“","Ein einzelnes Gegenbeispiel kann eine Aussage über alle Mitglieder einer Gruppe grundsätzlich nicht widerlegen, mit oder ohne „wirklich“.","Nach der Verschärfung bleibt die Aussage prüfbar, gilt aber nur noch für eine kleine Gruppe von Menschen und ist deshalb unbedeutend."],"correctIndex":1,"explanation":"Vorher war die Behauptung prüfbar: Ein Gesundheitsinteressierter mit schlechter Ernährung hätte sie widerlegt. Genau so jemand wurde genannt. Marta rettet ihre Aussage, indem sie das Gegenbeispiel aus der Kategorie wirft. Das Kriterium für „wirklich interessiert“ ist nun genau das, was behauptet wird, und die Aussage lautet im Kern: „Wer sich bewusst ernährt, ernährt sich bewusst.“ Das ist immer wahr und sagt nichts mehr über die Welt. Ein Gegenbeispiel kann eine Allaussage durchaus widerlegen. Gerade deshalb wird es ausgeschlossen.","coreRule":"⚡ Prüfe, ob sich das Kriterium für „wirklich“ unabhängig von der Behauptung bestimmen lässt; sonst ist die Behauptung leer.","beleg":"Werkstück D.3.5 (Kontext & Tiefe, „Der Mechanismus“)","status":"entwurf","scenario":"","kurz":"Marta macht „bewusste Ernährung“ zum Kriterium für „wirkliches Interesse“, also gerade zu dem, was sie behauptet. Der Satz kann dann nie mehr falsch sein und sagt nichts mehr über die Welt; das Gegenbeispiel hätte ihn vorher durchaus widerlegt.","prueffrage":"Welches Ergebnis hätte Martas Aussage vorher widerlegt, und gibt es dieses Ergebnis nach ihrer Antwort noch?","rueckmeldung":[{"option":0,"text":"Zur bloßen Meinung wird die Aussage durch „wirklich“ nicht, und ob sie jemanden verletzt, spielt für ihre Prüfbarkeit keine Rolle. Sie wird zu einem Satz, der per Definition immer stimmt und deshalb nichts mehr über die Welt sagt."},{"option":2,"text":"Ein einzelnes Gegenbeispiel kann eine Aussage über alle sehr wohl widerlegen. Hier greift es nur deshalb nicht mehr, weil Marta es mit „nicht wirklich“ aus der Gruppe herausdefiniert."},{"option":3,"text":"Dass die Gruppe schrumpft, stimmt. Prüfbar bleibt die Aussage danach aber nicht: Wer sich nicht bewusst ernährt, zählt nun per Definition nicht dazu. Das macht sie wertlos, nicht ihre geringe Reichweite."}],"familie":"definition-nachtraeglich","fertigkeit":"F2"},{"id":"qx-d2-011","clusterId":"D","werkstueckRef":"D.3.5","stufe":3,"question":"Zwei Sätze fallen im Gespräch. Satz 1: „Ein echter Freund würde dich nicht belügen.“ Satz 2: „Alle meine Freunde sind ehrlich zu mir. Klar, Jonas hat mich neulich angelogen, aber dann war er eben kein echter Freund.“ Was unterscheidet die beiden Sätze?","options":["Im ersten Satz setzt der Sprecher einen Maßstab dafür, wie Freundschaft sein sollte. Im zweiten rettet er eine Tatsachenbehauptung vor einem Gegenbeispiel, indem er den Begriff „Freund“ nachträglich verengt.","Im ersten Satz kommt das Wort „echt“ vor, im zweiten Satz kommt es erst nach einem Gegenbeispiel vor. Allein die Reihenfolge der Wörter macht den zweiten Satz zum Fehlschluss.","Im ersten Satz spricht der Sprecher über Freundschaft allgemein, im zweiten über eine einzelne Person. Allgemeine Aussagen über Freundschaft sind grundsätzlich unangreifbar.","Im ersten Satz widerspricht niemand, im zweiten schon. Ohne Widerspruch kann in keinem Gespräch ein Fehlschluss entstehen, mit Widerspruch immer."],"correctIndex":0,"explanation":"Eine Norm („Ein echter Freund sollte nicht lügen“) behauptet nichts über die Welt, sondern legt fest, was man von Freunden erwartet. Ein Gegenbeispiel kann sie deshalb nicht widerlegen, und sie muss es auch nicht. Der zweite Satz dagegen ist eine Tatsachenbehauptung („Alle meine Freunde sind ehrlich“). Als Jonas sie widerlegt, wird nicht die Behauptung geprüft, sondern der Begriff „Freund“ nachträglich so verengt, dass Jonas herausfällt. Am Ende steht: „Alle ehrlichen Freunde sind ehrlich“, eine Aussage, die nichts mehr behauptet und nicht mehr falsch sein kann. Verräterisch ist der Wechsel von der Frage „Stimmt das?“ zur Frage „Wer zählt überhaupt dazu?“. Das Wort „echt“ allein macht noch keinen Fehlschluss, entscheidend ist, wozu es dient: Maßstab setzen oder Tatsache gegen Evidenz verteidigen.","coreRule":"⚡ Normen setzen ist erlaubt, Tatsachen mit einer nachträglichen Definition retten nicht.","beleg":"Werkstück D.3.5 (Das Adaptive Talent; Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"","kurz":"Satz 1 setzt einen Maßstab und behauptet nichts über die Welt, ein Gegenbeispiel kann ihn nicht widerlegen. Satz 2 ist eine Tatsachenbehauptung, die ihr Gegenbeispiel wegdefiniert, statt sich prüfen zu lassen.","prueffrage":"Was müsste passieren, damit der Sprecher seine Aussage über seine Freunde als falsch gelten lässt?","rueckmeldung":[{"option":1,"text":"Beide Sätze benutzen das Wort „echt“, das stimmt. Fehlerhaft macht den zweiten aber nicht die Wortstellung, sondern wozu „echt“ dient: Es rettet eine Tatsachenbehauptung vor dem Gegenbeispiel, statt einen Maßstab zu setzen."},{"option":2,"text":"Satz 1 ist allgemein, Satz 2 nennt Jonas, das stimmt. Doch auch Satz 2 ist eine Allaussage („Alle meine Freunde …“), und eine Tatsachenbehauptung bleibt widerlegbar, wie allgemein sie auch ist. Den Unterschied macht die Art der Aussage."},{"option":3,"text":"Tatsächlich kommt nur im zweiten Satz ein Einwand vor. Zum Fehlschluss führt aber erst die Reaktion darauf: Statt die Behauptung zu prüfen, wird der Begriff „Freund“ nachträglich so verengt, dass der Einwand herausfällt."}],"familie":"definition-nachtraeglich","fertigkeit":"F2"},{"id":"qx-d2-012","clusterId":"D","werkstueckRef":"D.3.5","stufe":4,"question":"Welche Rückfrage prüft die Behauptung des Coaches am besten?","scenario":"Ein Diätcoach sagt: „Wer sich wirklich an den Plan hält, nimmt ab. Wer nicht abnimmt, hat sich eben nicht wirklich daran gehalten.“","options":["Warum hat der Plan bei dir nicht gewirkt, und was hast du anders gemacht als andere?","Ist es nicht seltsam, dass so viele scheitern, wenn der Plan angeblich so einfach ist?","Kannst du beweisen, dass der Plan nicht wirkt, oder muss ich dem Coach recht geben?","Woran erkennt man vorab, wer sich richtig an den Plan gehalten hat, unabhängig vom Abnehmen?"],"correctIndex":3,"explanation":"Der Coach verschärft die Bedingung nachträglich: „Sich wirklich an den Plan halten“ heißt in seinem Satz faktisch „hat abgenommen“. Dadurch wird die Behauptung zur Tautologie („Wer abnimmt, nimmt ab“) und kann nie mehr widerlegt werden, denn jedes Scheitern wird einfach dem Anwender zugeschrieben. Die beste Prüfung verlangt ein Kriterium für „wirklich gehalten“, das unabhängig vom Ergebnis feststellbar ist, etwa Ernährungstagebuch, Wiegen der Portionen oder Kontrolle durch Dritte. Gibt es ein solches Kriterium nicht, sagt die Behauptung nichts über den Plan aus. Die anderen Fragen sind persönlich, suggestiv oder kehren die Beweislast um: Der Coach müsste seine Behauptung belegen, nicht die Gegenseite ihre Widerlegung.","coreRule":"⚡ Verlange ein Kriterium für „echt“ oder „wirklich“, das nicht schon das Ergebnis voraussetzt.","beleg":"Werkstück D.3.5 (Anwendung & Relevanz, „Pseudowissenschaft & Kulte“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Der Satz des Coaches ist so gebaut, dass er nie falsch sein kann: Wer nicht abnimmt, hat sich eben „nicht wirklich“ gehalten. Prüfbar wird er erst, wenn man das Halten unabhängig vom Ergebnis feststellen kann, etwa per Tagebuch.","prueffrage":"Welches Ergebnis eines Teilnehmers könnte der Coach überhaupt als Fehlschlag seines Plans anerkennen?","rueckmeldung":[{"option":0,"text":"Nach Gründen zu fragen, wirkt interessiert und freundlich. Die Frage richtet sich aber auf die Person statt auf die Behauptung, und sie klärt nicht, woran sich „wirklich gehalten“ überhaupt erkennen lässt."},{"option":1,"text":"Die Frage wirkt kritisch, ist aber suggestiv: Sie unterstellt, der Plan gelte als einfach und viele scheiterten, obwohl davon keine Rede war. Die eigentliche Schwäche, dass „wirklich gehalten“ nur am Ergebnis gemessen wird, bleibt unberührt."},{"option":2,"text":"Ein Beweis gegen den Plan wirkt wie ein fairer Test. Die Beweislast liegt aber beim Coach, der etwas behauptet, und das Entweder-oder („beweisen oder recht geben“) lässt keinen Raum für die Frage, ob die Behauptung überhaupt prüfbar ist."}],"familie":"definition-nachtraeglich","fertigkeit":"F2"},{"id":"qx-d2-013","clusterId":"D","werkstueckRef":"D.3.6","stufe":1,"question":"Was ist an dieser Begründung das Problem?","scenario":"„Wie funktioniert die Wünschelrute?“ – „Sie reagiert auf Erdstrahlen.“ – „Was sind Erdstrahlen?“ – „Das, worauf die Wünschelrute reagiert.“","options":["Jede Seite stützt nur die andere; für keine von beiden gibt es einen unabhängigen Beleg.","Die Wünschelrute ist bisher nur durch Erfahrungsberichte gestützt, nicht durch Messungen; deshalb bleibt sie eine bloße Anekdote.","Der Begriff „Erdstrahlen“ ist zu unscharf definiert; mit einer genaueren Definition wäre die Begründung in Ordnung.","Der Sprecher beruft sich auf eine unsichtbare Kraft; unsichtbare Dinge dürfen nie Teil einer Begründung sein."],"correctIndex":0,"explanation":"Die Wirkung der Rute wird mit Erdstrahlen erklärt, und Erdstrahlen werden nur darüber bestimmt, dass die Rute auf sie reagiert. Beide Behauptungen stützen sich gegenseitig, und es fehlt der Anker in der überprüfbaren Realität: ein Beleg für eines von beiden, der nichts mit dem anderen zu tun hat. Das ist ein Zirkelschluss (petitio principii): Die Begründung setzt voraus, was sie begründen soll. Auch eine genauere Definition würde den Kreis nicht öffnen, solange sie sich wieder nur auf die Rute beruft. Und unsichtbare Dinge sind nicht grundsätzlich verboten, denn Elektronen sind auch unsichtbar. Entscheidend ist, ob es unabhängige Belege gibt, etwa Messungen, die nicht von der Rute abhängen.","coreRule":"⚡ Frag nach einem Beleg für eine der beiden Seiten, der nichts mit der anderen zu tun hat.","beleg":"Werkstück D.3.6 (Anwendung & Relevanz, „Pseudowissenschaft“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Die Rute soll durch Erdstrahlen erklärt werden, die Erdstrahlen aber nur dadurch, dass die Rute auf sie reagiert. So stützen sich beide gegenseitig, und es fehlt ein unabhängiger Beleg. Die Begründung setzt voraus, was sie zeigen soll.","prueffrage":"Was erfährst du über Erdstrahlen, wenn du die zweite Antwort in die erste einsetzt?","rueckmeldung":[{"option":1,"text":"Ob es für die Wünschelrute Messungen gibt, ist in diesem Wortwechsel gar nicht die Frage. Das Problem zeigt sich schon in ihm selbst: Rute und Erdstrahlen werden nur durcheinander erklärt, die Begründung dreht sich im Kreis."},{"option":2,"text":"Der Begriff ist tatsächlich leer, doch Schärfe allein hilft nicht: Eine Definition, die sich wieder nur auf die Rute beruft, schließt den Kreis nur enger. Öffnen könnten ihn erst Messungen, die von der Rute unabhängig sind."},{"option":3,"text":"Unsichtbares klingt verdächtig, ist aber nicht grundsätzlich ausgeschlossen: Auch Elektronen sieht man nicht, und sie sind belegt. Es kommt nicht auf die Sichtbarkeit an, sondern darauf, ob unabhängige Belege vorliegen."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2"},{"id":"qx-d2-014","clusterId":"D","werkstueckRef":"D.3.6","stufe":2,"question":"Eine Anhängerin sagt: „Unsere Gruppe liegt richtig, weil nur wahre Mitglieder die Wahrheit erkennen, und wer die Wahrheit erkennt, ist ein wahres Mitglied.“ Ein Kritiker wendet ein: „Aber Mitglied X hat Gelder veruntreut.“ Sie antwortet: „Dann war er nie ein wahres Mitglied.“ Welche Analyse beschreibt beide Aussagen der Anhängerin am treffendsten?","options":["Die erste Aussage setzt voraus, was sie beweisen soll, und sichert so die Grundbehauptung ab; die zweite weist einen Einwand ab, indem sie den Begriff „wahres Mitglied“ nachträglich enger zieht.","Die erste Aussage weist einen Einwand ab, indem sie den Begriff „wahres Mitglied“ nachträglich enger zieht; die zweite setzt voraus, was sie beweisen soll, und sichert so die Grundbehauptung ab.","Beide Aussagen haben denselben Fehler, nur in zwei Formulierungen: Die zweite Aussage wiederholt lediglich die erste in anderen Worten.","Beide Aussagen sind keine Fehlschlüsse, weil jede Gruppe das Recht hat, ihre Begriffe selbst festzulegen und gegen Einzelfälle zu verteidigen."],"correctIndex":0,"explanation":"Die erste Aussage ist ein Zirkelschluss: „Wahr ist, was wahre Mitglieder erkennen“ und „wahres Mitglied ist, wer das Wahre erkennt“ stützen sich gegenseitig, ohne dass irgendein Beleg von außen hinzukommt. Die zweite Aussage hat eine andere Funktion: Sie reagiert auf einen konkreten Einwand und rettet die Behauptung, indem der Begriff „wahres Mitglied“ im Nachhinein so definiert wird, dass der Gegenfall nicht mehr zählt (der „Kein wahrer Schotte“-Trick). Die zweite Aussage wiederholt die erste also nicht in anderen Worten, sondern antwortet auf einen Angriff von außen. Es sind zwei verschiedene Fehler: Der eine baut die Struktur des Dogmas, der andere ist die Verteidigungstaktik dagegen. Dass eine Gruppe ihre Begriffe frei setzen darf, ändert nichts daran, dass solche Setzungen nichts beweisen.","coreRule":"⚡ Wer den Beweis in die Behauptung einbaut, baut einen Kreis (Zirkelschluss); wer den Begriff nach dem Einwand enger zieht, verteidigt ihn (Kein wahrer Schotte).","beleg":"Werkstück D.3.6 (Kontext & Tiefe, „Abgrenzung zum Kein wahrer Schotte“; Verbindungen)","status":"entwurf","scenario":"","kurz":"Die erste Aussage stützt sich nur selbst: Die Wahrheit erkennen nur wahre Mitglieder, und wahres Mitglied ist, wer die Wahrheit erkennt. Die zweite zieht den Begriff erst nach dem Einwand enger. Das sind zwei Fehler: ein Zirkel und eine nachträgliche Rettung.","prueffrage":"Was müsste die Anhängerin vorlegen, damit ein Außenstehender ihre Grundbehauptung prüfen kann?","rueckmeldung":[{"option":1,"text":"Die Reihenfolge im Gespräch spricht dagegen: Der Einwand kommt erst, nachdem der erste Satz gefallen ist, also kann dieser ihn gar nicht abwehren. Erst die Antwort „nie ein wahres Mitglied“ zieht den Begriff nachträglich enger."},{"option":2,"text":"Beide Sätze schützen die Gruppe, das stimmt. Die zweite Aussage wiederholt die erste aber nicht, sondern antwortet auf einen konkreten Angriff von außen. Es sind zwei verschiedene Fehler: der eine baut das Dogma, der andere verteidigt es."},{"option":3,"text":"Begriffe zu setzen steht jeder Gruppe frei, aber solche Setzungen beweisen nichts. Hier stützt der erste Satz sich nur selbst, und im zweiten wird die Definition erst nach dem Einwand so zugeschnitten, dass der Gegenfall nicht mehr zählt."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2"},{"id":"qx-d2-015","clusterId":"D","werkstueckRef":"D.3.6","stufe":3,"question":"Ein Kollege argumentiert: „Meine Methode ist zuverlässig. Warum? Weil sie funktioniert – und dass sie funktioniert, sieht man daran, dass sie zuverlässig ist.“ Du entgegnest, das sei ein Zirkelschluss. Er kontert: „Aber logisch ist das einwandfrei: Wenn die Prämisse stimmt, stimmt auch die Schlussfolgerung.“ Warum ändert dieser Einwand nichts daran, dass das Argument nichts beweist?","options":["Weil die Form „P, also P“ logisch ungültig ist: Aus einer Aussage folgt sie selbst nicht, solange keine zweite Prämisse dazukommt.","Weil die Prämisse in jedem Zirkelschluss falsch ist und ein Schluss aus einer falschen Prämisse nichts beweist.","Weil der Schluss gültig ist, die Prämisse aber nicht besser gestützt ist als die Konklusion, die sie stützen soll.","Weil das Argument keine Prämisse enthält, sodass es nichts gibt, woraus sich etwas folgern ließe."],"correctIndex":2,"explanation":"Gültigkeit und Beweiskraft sind zwei verschiedene Dinge. „P, also P“ ist formal gültig: Wenn die Prämisse stimmt, stimmt auch die Konklusion. Aber die Prämisse taugt nur so viel wie die Konklusion, die sie stützen soll – hier sagt sie schlicht dasselbe in anderen Worten. Ein solches Argument predigt nur zu denen, die bereits glauben. Der Einwand des Kollegen trifft also ins Leere: Die Form ist in Ordnung, aber es fehlt ein unabhängiger, externer Anker, der die Prämisse trägt.","coreRule":"⚡ Gültig ist nicht beweisend: Ein Schluss, der sein Ergebnis voraussetzt, überzeugt nur Überzeugte.","beleg":"Werkstück D.3.6 (Kontext & Tiefe, „Logische Form“ und „Mechanik des Beweisgrund-Erschleichens“)","status":"entwurf","scenario":"","kurz":"Der Schluss ist formal gültig, aber die Prämisse „sie funktioniert“ sagt nur dasselbe wie die Konklusion und ist nicht besser gestützt. Gültigkeit ist nicht Beweiskraft: Es fehlt ein unabhängiger Anker.","prueffrage":"Was müsste der Kollege zusätzlich vorlegen, damit jemand, der an der Methode zweifelt, überzeugt wäre?","rueckmeldung":[{"option":0,"text":"Dass hier nichts bewiesen wird, stimmt, aber nicht wegen der Form. „P, also P“ ist gültig: Ist die Prämisse wahr, ist es die Konklusion auch. Der Mangel liegt darin, dass die Prämisse keinen eigenen Halt hat."},{"option":1,"text":"Aus einer falschen Prämisse wäre tatsächlich nichts bewiesen. Die Prämisse eines Zirkelschlusses muss aber nicht falsch sein: Die Methode könnte durchaus zuverlässig sein. Es fehlt nur ein unabhängiger Grund, das zu glauben."},{"option":3,"text":"Eine Prämisse ist durchaus vorhanden: „Sie funktioniert.“ Sie sagt nur in anderen Worten dasselbe wie die Konklusion und trägt deshalb nichts Eigenes bei. Vorhanden ist sie aber, sie stützt nur nichts."}],"familie":"zirkelschluss-erkennen","fertigkeit":"F2"},{"id":"qx-d2-016","clusterId":"D","werkstueckRef":"D.3.6","stufe":4,"question":"Beide Argumente sind gleich gebaut. Worin liegt trotzdem der entscheidende Unterschied?","scenario":"Zwei Argumente im Vergleich:\\n\\n(1) „Elektronen gibt es, denn in der Nebelkammer sehen wir Spuren, und solche Spuren sind die Signatur von Elektronen.“\\n\\n(2) „Gott existiert, denn die Bibel sagt es, und die Bibel ist Gottes Wort.“\\n\\nBeide Male wird die Behauptung teilweise schon in der Begründung vorausgesetzt.","options":["Beim Elektronen-Argument sind andere Deutungen der Spuren sehr unwahrscheinlich, beim Bibel-Argument gibt es viele plausible andere Deutungen.","Beim Elektronen-Argument stammen die Belege aus Messungen, und Messdaten dürfen im Kreis argumentieren, geschriebene Texte dagegen nie.","Beim Elektronen-Argument ist die Behauptung vergleichsweise jung, deshalb genügen dafür weniger strenge Belege als bei einer alten Behauptung.","Beim Elektronen-Argument ist die Behauptung in den Prämissen gar nicht enthalten, deshalb ist nur dieses Argument ein gültiger Beweis."],"correctIndex":0,"explanation":"Nicht jede stillschweigende Voraussetzung ist ein Fehlschluss. Auch in der Wissenschaft wird überall dort, wo Dinge nicht direkt beobachtbar sind, auf die beste Erklärung geschlossen, und dieser Schluss hat dieselbe Form wie das zweite Argument. Den Unterschied machen die Wahrscheinlichkeiten: Für die Bibel gibt es viele andere plausible Deutungen, als dass sie Gottes Wort ist; beim Elektronen-Schluss ist das nicht der Fall. Weder die Art der Quelle noch das Alter der Behauptung macht den Unterschied. Auch ist die Behauptung in beiden Fällen teilweise schon in der Begründung enthalten, sonst wäre der Vergleich nicht gleich gebaut. Untersuchungen zur Stärke von Argumenten (Hahn und Oaksford, 2006, 2007) zeigen, dass dieselbe Argumentform je nach Inhalt unterschiedlich stark sein kann.","coreRule":"⚡ Gleiche Form heißt nicht gleiche Beweiskraft: Frag, wie plausibel die Alternativen zur vorgeschlagenen Erklärung sind.","beleg":"Werkstück D.3.6 (Der Kipppunkt); Fn. gl-d-hahn (Hahn/Oaksford 2006, S. 16–17)","status":"entwurf","kurz":"Beide Schlüsse haben dieselbe Form, und eine stillschweigende Voraussetzung allein macht noch keinen Fehlschluss. Entscheidend ist, wie viele andere plausible Deutungen es gibt: bei der Bibel viele, bei den Spuren in der Nebelkammer kaum.","prueffrage":"Wenn Fachleute die Spuren in der Nebelkammer und den Bibeltext untersuchen: Wie einig sind sie sich jeweils über deren Herkunft?","rueckmeldung":[{"option":1,"text":"Die Spuren stammen tatsächlich aus Messungen, und das wirkt solider als ein Text. Eine Regel, nach der Messdaten im Kreis argumentieren dürfen, Texte aber nie, gibt es jedoch nicht: Die Art der Quelle entscheidet nicht über die Stärke des Arguments."},{"option":2,"text":"Junge Behauptungen nachsichtiger zu behandeln, mag fair wirken. Doch das Alter einer Behauptung sagt nichts über ihre Wahrheit und ändert nicht, welche Belege sie braucht; den Unterschied machen die anderen plausiblen Deutungen."},{"option":3,"text":"Das Elektronen-Argument wirkt sauberer, doch auch dort steckt die Behauptung teilweise in der Begründung, sonst wären beide nicht gleich gebaut. Es ist kein strenger Beweis, sondern ein Schluss auf die beste Erklärung."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4"},{"id":"qx-d2-017","clusterId":"D","werkstueckRef":"D.3.7","stufe":1,"question":"Was haben beide Aussagen gemeinsam, und worin unterscheiden sie sich?","options":["Beide urteilen allein nach der Herkunft; der Unterschied liegt in der Richtung: Der eine verwirft die Studie wegen ihrer Quelle, der andere übernimmt sie deswegen.","Beide urteilen allein nach der Herkunft; der Unterschied liegt darin, dass nur der erste Kollege einen Denkfehler macht, weil Misstrauen immer unbegründeter ist als Vertrauen.","Beide urteilen allein nach der Herkunft; der Unterschied liegt darin, dass der erste Kollege eine Person angreift und der zweite eine Idee verteidigt.","Beide urteilen allein nach der Herkunft; der Unterschied liegt darin, dass der erste Kollege die Studie vorsichtig prüft und der zweite sie endgültig verwirft."],"correctIndex":0,"explanation":"Beide Kollegen schließen allein von der Herkunft auf die Wahrheit, ohne Inhalt, Logik oder Evidenz anzusehen. Der eine macht den genetischen Fehlschluss („schlechte Quelle, also falsch“), der andere den Appell an die Autorität („gute Quelle, also wahr“); beide Fehler sind spiegelbildlich gebaut. Eine schlechte Bilanz der Quelle darf Anlass sein, besonders kritisch zu prüfen, ein guter Ruf Anlass zu Vertrauen, die Prüfung der Belege ersetzen kann aber beides nicht. Deshalb tragen die anderen Unterscheidungen nicht: Beide begehen einen Denkfehler, nicht nur der Misstrauische; keiner greift eine Person an oder verteidigt eine Idee, beide urteilen über dieselbe Quelle; und vorsichtig prüft keiner: Der erste verwirft die Studie, der zweite übernimmt sie. Ein sauberes Ergebnis bleibt sauber, auch wenn ein Konzern es bezahlt hat, und ein schwaches wird durch den Namen einer Universität nicht stärker.","coreRule":"⚡ Prüfe den Inhalt, nicht das Etikett der Herkunft, in beide Richtungen.","beleg":"Werkstück D.3.7 (Kernidee)","status":"entwurf","scenario":"Zwei Kollegen streiten über dieselbe Studie, ohne sie gelesen zu haben. Der erste sagt: „Die Studie ist von einem Pharmakonzern bezahlt, also ist ihr Ergebnis falsch.“ Der zweite sagt: „Die Studie stammt von einer renommierten Universität, also ist ihr Ergebnis richtig.“","kurz":"Beide beurteilen die Studie nur nach ihrer Herkunft, ohne Daten und Methode anzusehen. Der Unterschied liegt allein in der Richtung: Wer „schlechte Quelle, also falsch“ sagt, macht einen spiegelbildlichen Fehler zu „gute Quelle, also wahr“.","prueffrage":"Was haben die beiden Kollegen über die Studie selbst gesagt, und was davon betrifft ihren Inhalt?","rueckmeldung":[{"option":1,"text":"Dass beide nach der Herkunft urteilen, stimmt. Doch auch „gute Quelle, also wahr“ ist ein Fehlschluss, nur in die andere Richtung. Misstrauen darf Anlass sein, genauer hinzusehen, ersetzt aber nicht den Blick auf Daten und Methode."},{"option":2,"text":"Angriff und Verteidigung scheinen die beiden zu trennen, doch beide urteilen über dieselbe Studie nur nach ihrer Quelle: Der eine verwirft sie deswegen, der andere übernimmt sie deswegen. Der Unterschied liegt allein in der Richtung."},{"option":3,"text":"Vorsichtig prüft der erste Kollege gerade nicht: Er erklärt die Studie schon wegen des Geldgebers für falsch. Und der zweite verwirft nichts, er hält sie wegen der Universität für richtig."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-d2-018","clusterId":"D","werkstueckRef":"D.3.7","stufe":2,"question":"Welche Rückfrage prüft diese Behauptung am besten?","scenario":"In einer Diskussion über ein Förderprogramm sagt jemand: „Die Grundidee dieses Programms stammt ursprünglich von einer Lobbygruppe. Deshalb ist sie falsch, egal ob die Daten dazu etwas anderes zeigen.“ Die Daten zu dem Programm hat er sich nicht angesehen.","options":["Wie belastbar sind die Daten zum Programm, wenn du sie unabhängig davon betrachtest, wer die Grundidee zuerst entwickelt hat?","Warum vertrauen so viele Menschen dieser Lobbygruppe, obwohl sie eigene Interessen verfolgt?","Wie viele Leute, die das Programm unterstützen, haben schon einmal für diese Lobbygruppe gearbeitet?","Woher weißt du so genau, dass ausgerechnet diese Gruppe die Idee zuerst entwickelt hat?"],"correctIndex":0,"explanation":"Der Einwand verwirft eine Idee allein wegen ihres Ursprungs. Ob sie stimmt, hängt aber an Inhalt, Logik und Evidenz, nicht daran, wer sie zuerst hatte; deshalb lenkt die beste Rückfrage auf die Daten und trennt sie von der Herkunft. Die anderen Fragen bleiben bei Personen, Gruppen oder der Herkunftsgeschichte und prüfen den Inhalt nicht. Der Ursprung darf ein Anlass sein, genauer hinzuschauen und nach unabhängiger Bestätigung zu suchen, als Urteil über die Wahrheit taugt er nicht. Ein einfacher Prüftest: Stell dir vor, dieselbe Information stünde anonym auf einem Zettel, und bewerte dann die Belege.","coreRule":"⚡ Ursprung einer Idee ist ein Anlass zum Prüfen, kein Urteil.","beleg":"Werkstück D.3.7 (Kontext & Tiefe, „Abgrenzung zum Ad Hominem“)","status":"entwurf","kurz":"Eine Idee wird nicht falsch, nur weil eine Lobbygruppe sie hatte. Ob sie trägt, zeigen Inhalt und Daten. Die beste Rückfrage lenkt deshalb auf die Belege und trennt die Idee von ihrer Herkunft, statt über Personen oder Gruppen zu reden.","prueffrage":"Worauf stützt der Sprecher sein Urteil „falsch“, und was hat er sich dafür selbst angesehen?","rueckmeldung":[{"option":1,"text":"Dass eine Gruppe eigene Interessen hat, ist ein Grund, genauer hinzuschauen. Die Frage bleibt aber bei der Gruppe und ihrem Ansehen und sagt nichts darüber, ob die Daten zum Programm etwas zeigen."},{"option":2,"text":"Auffällige Verbindungen können Anlass für eine genauere Prüfung sein. Wer das Programm unterstützt und woher diese Leute kommen, sagt aber nichts über seine Wirkung. Die Frage bleibt bei Personen und prüft die Behauptung nicht."},{"option":3,"text":"Die Herkunft einer Aussage nachzuprüfen klingt gründlich. Selbst wenn sie sich bestätigte oder widerlegte, wäre über die Richtigkeit der Idee nichts entschieden, denn dafür zählen Inhalt und Belege."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-d2-019","clusterId":"D","werkstueckRef":"D.3.7","stufe":3,"question":"Welche Reaktion ist hier vernünftig, ohne in einen Denkfehler zu kippen?","scenario":"Dir liegt eine Studie vor, die von einem Konzern finanziert wurde, dem du misstraust. Du weißt, dass solche Auftraggeber in der Vergangenheit Studien manipuliert haben. Ein Bekannter sagt: „Die Studie kannst du dir sparen, die ist von denen bezahlt.“","options":["Die Studie gar nicht lesen, denn wer einmal manipuliert hat, dessen Ergebnisse sind automatisch unbrauchbar.","Die Studie ungeprüft annehmen, denn Misstrauen gegenüber dem Geldgeber ist selbst schon ein Denkfehler.","Die Studie besonders genau prüfen und nach unabhängiger Bestätigung suchen, denn die schlechte Bilanz verlangt mehr Sorgfalt.","Die Studie annehmen, sobald eine angesehene Institution sie bestätigt hat, denn gute Quellen sind automatisch wahr."],"correctIndex":2,"explanation":"Misstrauen gegenüber einer Quelle mit schlechter Bilanz ist berechtigt, solange es dazu führt, die Studie besonders kritisch zu prüfen und nach unabhängiger Bestätigung zu suchen. Zum Fehlschluss wird es, wenn die Herkunft allein als Beweis gegen den Inhalt gilt („von denen bezahlt, also falsch“, der genetische Fehlschluss). Eine Idee ist an Inhalt, Logik und Evidenz zu bewerten, nicht an ihrem Ursprung. Das Gegenstück, eine Quelle für unfehlbar zu halten, wäre der Appell an die Autorität.","coreRule":"⚡ Schlechte Bilanz heißt: genauer prüfen, nicht: ungelesen verwerfen.","beleg":"Werkstück D.3.7 (Der Kipppunkt)","status":"entwurf","kurz":"Misstrauen gegenüber einer Quelle mit schlechter Bilanz ist berechtigt, wenn es zu genauerer Prüfung und zur Suche nach unabhängiger Bestätigung führt. Zum Fehler wird es erst, wenn die Herkunft allein den Inhalt widerlegen soll.","prueffrage":"Was weißt du über diese konkrete Studie bisher, außer wer sie bezahlt hat?","rueckmeldung":[{"option":0,"text":"Dass der Geldgeber schon manipuliert hat, rechtfertigt Misstrauen. Daraus folgt aber nicht, dass jedes Ergebnis falsch ist: Ob die Studie trägt, zeigt sich an Methode, Daten und Schlüssen, nicht allein an ihrem Ursprung."},{"option":1,"text":"Misstrauen gegenüber einem Geldgeber mit schlechter Bilanz ist kein Denkfehler, sondern vernünftig. Es sollte nur in genaueres Hinsehen münden, nicht in Ablehnung. Ungeprüft anzunehmen, wäre das Gegenteil von Prüfen."},{"option":3,"text":"Eine unabhängige Bestätigung zu suchen, ist genau richtig. Dass ein angesehener Name allein Wahrheit garantiert, trägt aber nicht: Auch renommierte Institutionen irren, und entscheidend bleibt, was die Bestätigung inhaltlich zeigt."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-d2-020","clusterId":"D","werkstueckRef":"D.3.7","stufe":4,"question":"Welcher Schritt hilft dir am besten, die Bewertung des Punktes vom Absender zu trennen?","scenario":"Ein Gesetzesvorschlag der Partei, die du ablehnst, enthält einen Punkt, der dir eigentlich einleuchtet. Du merkst, dass du ihn vor allem wegen des Absenders ablehnen willst.","options":["Dem Punkt vorläufig zustimmen, um nicht voreingenommen zu wirken, und erst später prüfen, ob der Inhalt wirklich überzeugt.","Dich nur noch mit Vorschlägen von Parteien befassen, deren Herkunft und Absichten du kennst und billigst, und alle anderen ungelesen beiseitelegen.","Weitere Vorschläge derselben Partei lesen, bis du ihre Linie verstehst, und erst danach entscheiden, ob der Absender glaubwürdig ist.","Dir denselben Vorschlag ohne Absender oder von einer Seite vorstellen, der du vertraust, und prüfen, ob sich dein Urteil dann ändert."],"correctIndex":3,"explanation":"Deine Ablehnung gilt hier dem Absender, nicht dem Inhalt. Das ist ein genetischer Fehlschluss: Ob ein Vorschlag sinnvoll ist, hängt an Inhalt, Logik und Evidenz, nicht an seinem Ursprung. Der Gedankentest mit fehlendem oder vertauschtem Absender löst die Bewertung vom Ursprung und zeigt, ob du den Inhalt oder nur den Absender beurteilst. Nur Vorschläge gebilligter Parteien zu prüfen, wäre selbst ein Urteil nach Herkunft. Ein bloß vorläufiges Zustimmen oder das Abwarten, bis du den Absender einschätzen kannst, klammert die Herkunft nicht aus und bewertet den Inhalt nicht.","coreRule":"⚡ Stell dir die Information anonym vor: Hält der Inhalt dann stand?","beleg":"Werkstück D.3.7 (Anti-Denkmuster, Skript 1; Anwendung & Relevanz, „Politische Ideologie“)","status":"entwurf","kurz":"Stellst du dir denselben Vorschlag anonym oder von jemandem vor, dem du vertraust, siehst du, ob dein Urteil am Inhalt hängt oder am Absender. Ob ein Punkt sinnvoll ist, entscheiden Inhalt, Logik und Belege, nicht seine Herkunft.","prueffrage":"Welche Gründe gegen den Punkt selbst fallen dir ein, die nichts mit der Partei zu tun haben?","rueckmeldung":[{"option":0,"text":"Vorläufiges Zustimmen kann sich nach Fairness anfühlen, bleibt aber am Absender hängen: Du entscheidest weiter nach dem Image statt nach dem Inhalt und vertagst die eigentliche Prüfung nur."},{"option":1,"text":"Dass man auswählen muss, ist verständlich. Wer aber nur liest, was von gebilligten Parteien kommt, urteilt schon vorab nach Herkunft und begeht denselben Fehler systematisch. Gute Punkte anderer Absender erreichen dich gar nicht erst."},{"option":2,"text":"Die Linie einer Partei zu kennen, kann Kontext liefern. Doch die Frage, ob der Absender glaubwürdig ist, ersetzt nicht die Prüfung des Punktes selbst: Inhalt, Logik und Belege bleiben dabei unbewertet."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-d2-021","clusterId":"D","werkstueckRef":"D.3.8","stufe":1,"question":"Was ist an diesem Schluss logisch fehlerhaft?","scenario":"Auf einer Podiumsdiskussion verteidigt ein Erfinder sein Perpetuum mobile gegen die Kritik von Physikern: „Jede große Wahrheit wurde zuerst bekämpft. Meine Maschine wird bekämpft. Also steckt eine große Wahrheit darin.“","options":["Er kehrt eine Aussage um: Aus „Große Wahrheiten wurden zuerst bekämpft“ folgt nicht „Alles, was bekämpft wird, ist eine große Wahrheit“.","Er behauptet, große Wahrheiten würden zuerst bekämpft, obwohl die Wissenschaftsgeschichte kein einziges solches Beispiel kennt.","Er stützt sich auf zu wenige Beispiele verfolgter Genies; mit zehn weiteren Beispielen dieser Art wäre der Schluss dann gültig.","Er verwechselt Ursache und Wirkung, denn nicht die Ablehnung macht eine Theorie wahr, sondern die Wahrheit löst die Ablehnung aus."],"correctIndex":0,"explanation":"Der Schluss hat die Form „Alle A sind B, dies ist B, also ist dies A“: Aus „Große Wahrheiten wurden bekämpft“ folgt nicht „Alles Bekämpfte ist eine große Wahrheit“. Carl Sagan nennt Fulton und die Brüder Wright als Verlachte, aber auch Bozo den Clown. Ablehnung trifft Genies und Irrtümer gleichermaßen und unterscheidet beide deshalb nicht. Zehn weitere Beispiele verfolgter Genies würden den Schluss nicht gültig machen, weil nicht die Zahl der Beispiele fehlt, sondern die Schlussrichtung falsch ist. Und dass manche Außenseiter recht behielten, bestreitet der Schluss nicht; fehlerhaft ist erst der Umkehrschluss.","coreRule":"⚡ Dass manche Genies verlacht wurden, macht nicht jeden Verlachten zum Genie.","beleg":"Werkstück D.3.8 (Kernidee)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Aus „Große Wahrheiten wurden bekämpft“ folgt nicht „Was bekämpft wird, ist eine große Wahrheit“. Ablehnung trifft Genies wie Irrtümer gleichermaßen und trennt beide daher nicht; der Erfinder dreht die Schlussrichtung um.","prueffrage":"Wird nur Richtiges abgelehnt, oder gibt es auch abgelehnte Ideen, die sich später als Irrtum erwiesen?","rueckmeldung":[{"option":1,"text":"Beispiele gibt es durchaus, etwa Fulton oder die Brüder Wright, die zunächst verlacht wurden. Selbst wenn man die Prämisse gelten lässt, steckt der Fehler nicht in ihr, sondern darin, wie der Erfinder aus ihr folgert."},{"option":2,"text":"Mehr Beispiele wirken wie ein Beleg, doch hier fehlt keine Menge. Selbst zehn weitere verfolgte Genies würden die Schlussrichtung nicht richtig machen, und die ist das Problem."},{"option":3,"text":"Der Schluss behauptet gar keinen Ursache-Wirkungs-Zusammenhang, er schließt von „wird bekämpft“ auf „ist eine große Wahrheit“. Auch dass Wahrheit allein Ablehnung auslöst, gilt nicht allgemein, denn Ablehnung hat viele Gründe."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2"},{"id":"qx-d2-022","clusterId":"D","werkstueckRef":"D.3.8","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","options":["Aus „Manche echten Neuerer wurden zunächst abgelehnt“ folgt nicht „Wer abgelehnt wird, ist ein echter Neuerer“.","Aus „Fachleute irren sich praktisch nie“ folgt, dass abgelehnte Theorien fast immer falsch sind, auch ohne Beleg im Einzelfall.","Aus „Außenseiter behalten insgesamt häufiger recht“ folgt, dass seine Ablehnung eher ein Zeichen künftigen Erfolgs ist.","Aus „Ablehnung zählt nur bei mehreren Fachrichtungen zugleich“ folgt, dass seine Ablehnung hier kaum als Argument gilt."],"correctIndex":0,"explanation":"Der Schluss kehrt eine wahre Aussage unzulässig um: Dass einige Genies zunächst abgelehnt wurden, heißt nicht, dass jeder Abgelehnte ein Genie ist. Abgelehnt werden auch unzählige Theorien, die sich als falsch erweisen, nur bleiben sie nicht in Erinnerung, weil niemand ihre Geschichten erzählt. Ablehnung trifft Genie und Irrtum gleichermaßen und trennt beide deshalb nicht, ganz gleich, aus wie vielen Fachrichtungen sie kommt. Dass Fachleute sich praktisch nie irren, stimmt ebenso wenig, und dass Außenseiter insgesamt häufiger recht hätten, ist durch nichts gedeckt. Entscheidend ist, ob die Theorie prüfbare Belege oder Vorhersagen liefert, so wie Galilei Beobachtungen hatte, die jeder mit einem Fernrohr nachprüfen konnte.","coreRule":"⚡ Ablehnung allein beweist nichts: Zähle auch die Bozos, nicht nur die Galileis, und frage nach prüfbaren Belegen.","beleg":"Werkstück D.3.8 (Kontext & Tiefe, „Die Basisrate wird unterschlagen“; Das Adaptive Talent)","status":"entwurf","scenario":"Auf einer Veranstaltung stellt ein Redner seine neue Theorie über die Ursache einer Krankheit vor. Nach Belegen gefragt, legt er keine eigenen Daten vor und sagt: „Meine Theorie wird von allen Fachleuten abgelehnt. Das zeigt, dass ich ein Genie bin – über Galilei haben sie auch gelacht.“","quote":"","quoteLabel":"","kurz":"Dass einige Genies zunächst abgelehnt wurden, macht nicht jeden Abgelehnten zum Genie: Abgelehnt werden auch unzählige Theorien, die sich als falsch erweisen. Ablehnung trennt beide nicht, entscheidend sind prüfbare Belege.","prueffrage":"Wie viele abgelehnte Theorien kennst du, die sich später als falsch erwiesen haben, und wer erzählt ihre Geschichten?","rueckmeldung":[{"option":1,"text":"Fachleute liegen oft richtig, aber dass sie sich „praktisch nie“ irren, stimmt nicht: Auch Konsense waren schon falsch. Und selbst wenn die Ablehnung meist berechtigt ist, ersetzt dieser Schluss nicht die Prüfung der Theorie selbst."},{"option":2,"text":"Einzelne Außenseiter behielten tatsächlich recht, und genau von ihnen hört man. Dass sie insgesamt häufiger recht hätten, ist aber nicht gedeckt, denn die vielen gescheiterten Außenseiter fehlen in der Erinnerung."},{"option":3,"text":"Dass Ablehnung hier wenig beweist, stimmt. Der Grund liegt aber nicht in der Zahl der Fachrichtungen: Abgelehnt werden Genies wie Irrtümer, deshalb taugt Ablehnung allein nicht, um beide zu unterscheiden."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2"},{"id":"qx-d2-023","clusterId":"D","werkstueckRef":"D.3.8","stufe":3,"question":"Welche Rückfrage trifft die Schwäche des Vergleichs am besten?","scenario":"In einer Diskussion über eine neue „Ursache“ einer Krankheit sagt ein Redner: „Die Fachleute lehnen meine These ab. Genau wie bei Galilei: Der wurde von den Gelehrten seiner Zeit verfolgt, und am Ende hatte er recht.“ Du willst prüfen, ob dieser Vergleich trägt.","options":["Welche Vorhersage deiner These kann jeder unabhängig überprüfen?","Wie viele deiner Kritiker sind wirklich Fachleute in dieser Frage?","Warum sollten wir deiner Darstellung der Wissenschaftsgeschichte glauben?","Wie erklärst du dir, dass so viele Fachleute denselben Fehler machen?"],"correctIndex":0,"explanation":"Der Vergleich schließt von „Galilei wurde abgelehnt und hatte recht“ auf „ich werde abgelehnt, also habe ich recht“. Das ist ein ungültiger Umkehrschluss: Dass manche Genies abgelehnt wurden, sagt nichts über jeden, der abgelehnt wird, denn auch unzählige falsche Theorien wurden abgelehnt. Ablehnung ist daher kein Beleg, sondern trennt Genie und Irrtum nicht. Entscheidend ist, was die These an Prüfbarem vorlegt. Galilei überzeugte, weil jeder mit einem Fernrohr die Venusphasen und die Jupitermonde sehen konnte. Kepler bestätigte die Monde noch 1610, und die Mathematiker des Jesuitenkollegs in Rom bestätigten 1611 die Venusphasen und die vier Jupitermonde. Die Fachleute prüften also nach und gaben Galilei recht. Verurteilt wurde er erst 1633, und zwar von einer Glaubensbehörde, nicht von einer Fachgemeinschaft. Wer sich auf Galilei beruft, muss deshalb zeigen, was seine eigene These an prüfbaren Belegen hat. Die erste Rückfrage verlangt genau das und lenkt das Gespräch von der Verfolgung zurück zur Evidenz.","coreRule":"⚡ Abgelehnt zu werden ist kein Beleg. Entscheidend ist, was andere selbst prüfen können.","beleg":"Werkstück D.3.8 (Kontext & Tiefe, „Die Geschichte wird umgeschrieben“); Fn. gl-d-galileo (Finocchiaro 1989), gl-d-collegio (Favaro 1901, Bd. 11, Nr. 515 und 520, S. 87–88 und 92–93), gl-d-kepler (de Padova 2009). Magini (geprüft 12.10.2026 in Galileo, Le opere, Bd. 10 und 11): Kenntnis der „4 novis planetis“ belegt (Magini an Kepler, 20.4.1610); eigene Aufzeichnung der Monde nicht belegt (Magini an Galilei 23.10.1610: will Linsen erst noch testen; Cigoli an Galilei 23.8.1611: Magini beobachte laut Hörensagen „continuamente“ die vier Jupiterstelle). Halbsatz zu Magini deshalb gestrichen.","status":"entwurf","kurz":"Der Vergleich schließt von „Galilei wurde abgelehnt und hatte recht“ auf „ich werde abgelehnt, also habe ich recht“. Abgelehnt wurden aber auch unzählige falsche Theorien; wichtig ist, was die These an Prüfbarem vorlegt.","prueffrage":"Wie viele andere abgelehnte Thesen aus der Geschichte kennst du, die sich am Ende als falsch erwiesen?","rueckmeldung":[{"option":1,"text":"Ob die Kritiker wirklich Fachleute sind, ist eine berechtigte Frage, klärt aber nur, wie viel ihre Kritik wiegt. Der Fehler im Vergleich bleibt unberührt, denn auch Ablehnung durch echte Fachleute würde nicht zeigen, dass die These stimmt."},{"option":2,"text":"Quellen kritisch zu prüfen, ist hier nicht abwegig: Fachleute prüften Galileis Beobachtungen und bestätigten sie. Doch auch eine stimmige Geschichte würde die eigene These nicht stützen, und die Frage zielt auf den Redner statt auf Belege."},{"option":3,"text":"Die Frage übernimmt schon die Annahme, dass die Fachleute einen Fehler machen, und lädt zur Rechtfertigung der Verfolgungserzählung ein. Offen bleibt, was die These selbst an Prüfbarem vorlegt. Nur das trennt Genie und Irrtum."}],"familie":"ablehnung-ist-kein-beleg","fertigkeit":"F2"},{"id":"qx-d2-024","clusterId":"D","werkstueckRef":"D.3.8","stufe":4,"question":"Was macht diese Argumentation unwiderlegbar?","scenario":"Ein „Heiler“, dem die Zulassung entzogen wurde, schreibt: „Wenn es nicht stimmen würde, würden sie sich nicht so viel Mühe geben, es zu unterdrücken.“","options":["Der Heiler unterstellt seinen Kritikern Motive, die diese nie genannt haben, und widerlegt dann diese erfundenen Motive.","Der Heiler nennt keine Quelle für die Behauptung, er werde unterdrückt, und lässt seine Kritiker damit ohne Anhaltspunkt für eine Gegenprüfung.","Der Heiler beruft sich auf eine Behörde, die ihn bestraft hat, und macht damit deren Autorität zum Maßstab seiner Behauptung.","Der Heiler wertet jede Reaktion der Gegenseite als Bestätigung: Zustimmung und Widerstand passen gleichermaßen zu seiner These."],"correctIndex":3,"explanation":"Wer Gegenwehr als Beleg wertet, macht seine These unangreifbar: Zustimmung und Ablehnung stützen sie nun gleichermaßen – das ist die vollständige Immunisierung. Eine solche These lässt sich durch keine Reaktion der Gegenseite mehr widerlegen. Die Frage ist also nicht, wie die Kritiker reagieren, sondern welche prüfbare Vorhersage die These macht: Welche Beobachtung würde sie widerlegen? Und was legt der Heiler vor, das andere unabhängig nachprüfen können? Auch Galilei überzeugte nicht durch seine Verfolgung, sondern dadurch, dass jeder durch sein Fernrohr die Jupitermonde und die Venusphasen selbst sehen konnte.","coreRule":"⚡ Eine These, die durch Zustimmung und Ablehnung gleichermaßen bestätigt wird, ist nicht überprüfbar.","beleg":"Werkstück D.3.8 (Anwendung & Relevanz, „Verschwörungsmythen“ und „Pseudomedizin“; Anti-Denkmuster, Skript 2)","status":"entwurf","kurz":"Wer Gegenwehr als Beweis wertet, hat seine These gegen jede Widerlegung abgedichtet: Zustimmung wie Widerstand stützen sie. Entscheidend ist daher, welche prüfbare Vorhersage sie macht und welche Beobachtung sie widerlegen würde.","prueffrage":"Wie würde der Heiler es wohl deuten, wenn die Behörden ihn einfach in Ruhe ließen?","rueckmeldung":[{"option":0,"text":"Ein Strohmann würde Kritikern erfundene Motive zuschreiben und diese widerlegen. Der Heiler widerlegt hier aber nichts, sondern deutet jede Reaktion zu seinen Gunsten. Das macht die These unangreifbar, nicht eine Unterstellung."},{"option":1,"text":"Dass Prüfbares fehlt, ist ein berechtigter Einwand. Doch auch eine genannte Quelle würde nichts ändern, solange jede Reaktion als Bestätigung zählt. Unwiderlegbar wird die These durch diese Deutung, nicht durch fehlende Belege."},{"option":2,"text":"Der Heiler beruft sich hier nicht auf die Behörde, er stellt sich gegen sie. Die Verfolgung dient ihm als Beleg. Dass jede Reaktion als Bestätigung gilt, macht seine These unwiderlegbar, nicht ein Autoritätsargument."}],"familie":"immunisierung-erkennen","fertigkeit":"F2"},{"id":"qx-d2-025","clusterId":"D","werkstueckRef":"D.3.9","stufe":2,"question":"Was würde am besten klären, ob dein Gegenüber ehrlich nachfragt oder dich nur mit Fragen erschöpfen will?","scenario":"Unter deinem Beitrag zu einem umstrittenen Thema fragt jemand freundlich nach einer Quelle. Du lieferst sie. Die Antwort lautet: „Danke! Und hast du noch eine?“ Du lieferst eine zweite, wieder heißt es „Danke, und noch eine?“ Das wiederholt sich mehrmals, ohne dass je auf den Inhalt der Quellen eingegangen wird.","options":["Beobachten, was nach deiner Antwort geschieht: Arbeitet er mit ihr, prüft sie, widerspricht mit Gründen oder ändert etwas, oder folgt nur die nächste Frage?","Beobachten, ob er irgendwann unhöflich oder aggressiv wird, denn wer wirklich ehrlich fragt, bleibt auch bei Ablehnung dauerhaft freundlich.","Mitzählen, wie oft er zur selben Aussage nachfragt, denn ab der dritten Nachfrage weiß ein ehrlich Fragender längst genug.","Darauf achten, ob er Belege verlangt oder nach Meinungen und Gefühlen fragt, denn nur Belegfragen sind ein Zeichen echter Skepsis."],"correctIndex":0,"explanation":"Ob eine Nachfrage ehrlich ist, zeigt sich nicht an der einzelnen Frage, sondern an dem, was nach der Antwort geschieht. Wer wirklich verstehen oder prüfen will, geht auf das Gelieferte ein: Er stimmt zu, widerspricht mit Gründen, benennt, was ihn noch nicht überzeugt, oder ändert seine Meinung. Wer nur die nächste Frage stellt, ohne je etwas anzuerkennen, will nicht prüfen, sondern erschöpfen. Das Muster ist als „Sealioning“ bekannt: höfliche Dauerfragen als Belästigungstaktik. Der Tonfall taugt nicht als Kriterium, denn ausgesuchte Höflichkeit gehört zur Taktik. Auch eine feste Zahl an Nachfragen taugt nicht: Wer sich in eine Quelle vertieft, fragt vielleicht oft, arbeitet aber mit jeder Antwort. Und die Art der Frage unterscheidet ebenfalls nicht, denn auch ein Seelöwe verlangt ständig Belege, gerade für Beiläufiges und Selbstverständliches.","coreRule":"⚡ Prüf, ob dein Gegenüber mit deiner Antwort arbeitet oder nur die nächste Frage stellt.","beleg":"Werkstück D.3.9 (Der Seelöwe im Wohnzimmer; Kontext & Tiefe, „Die Kultur der Nachfrage“; Red Flags; Anti-Denkmuster, Skript 1; Fußnote gl-d-sealioning, Malki 2014)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Entscheidend ist, was nach deiner Antwort passiert: Wer wirklich prüfen will, geht auf das Gelieferte ein, stimmt zu oder widerspricht mit Gründen. Wer nur die nächste Frage stellt, will erschöpfen, auch wenn jede einzelne Frage höflich klingt.","prueffrage":"Würde sich jemand, der ehrlich fragt und sich gründlich einliest, im Ton oder in der Zahl der Fragen von deinem Gegenüber unterscheiden?","rueckmeldung":[{"option":1,"text":"Unhöflichkeit kann tatsächlich auf fehlendes Interesse hindeuten. Hier bleibt der Ton aber freundlich, und gerade ausgesuchte Höflichkeit gehört zur Taktik. Ein Kriterium muss beide Fälle trennen, und das leistet der Ton nicht."},{"option":2,"text":"Eine Häufung von Nachfragen kann ein Warnsignal sein. Eine feste Grenze trägt aber nicht: Wer sich in eine Quelle vertieft, fragt oft und arbeitet dennoch mit jeder Antwort. Die Anzahl sagt wenig darüber, ob die Antworten ankommen."},{"option":3,"text":"Belegfragen gehören zu echter Skepsis, wenn auf die Belege auch eingegangen wird. Als Unterscheidung taugen sie nicht, denn auch wer nur erschöpfen will, verlangt ständig Belege, gern für Selbstverständliches."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3"},{"id":"qx-d2-026","clusterId":"D","werkstueckRef":"D.3.9","stufe":3,"question":"Welche der vier Antworten ist eine legitime Nachfrage und kein Sealioning?","options":["„Danke für die Quelle. Und hast du noch eine? Und was genau meinst du mit ‚verringert‘? Und warum wirst du jetzt so unfreundlich zu mir?“","„Ich habe die Studie gelesen: Die Teilnehmer waren alle erwachsen. Gilt dein Schluss auch für Kinder, und wenn ja, woraus folgt das?“","„Interessant. Und hast du dafür auch eine Quelle? Ich frage ja nur, ein offenes Gespräch sollte so eine Frage doch aushalten, oder nicht?“","„Du hast deine Aussage öffentlich gemacht, für alle lesbar. Kannst du sie nicht verteidigen, oder willst du einfach keine vernünftige Diskussion führen?“"],"correctIndex":1,"explanation":"Eine legitime Nachfrage arbeitet mit der erhaltenen Antwort: Sie knüpft an das an, was der Beleg zeigt, und fragt gezielt nach der Lücke. Die anderen Beiträge nehmen die Antwort nicht auf: Sie fordern nur weitere Belege oder Erklärungen, ohne zu sagen, was an den bisherigen nicht genügt, oder sie stellen dein Verhalten statt deiner These in Frage. Gerade die höfliche Verpackung macht das gefährlich: Jede einzelne Frage wirkt harmlos, der Schaden wächst mit der Wiederholung, und wer die Geduld verliert, steht als der Unvernünftige da. Der Prüfstein ist nicht die Frage selbst, sondern was nach der Antwort geschieht: Wird mit ihr gearbeitet oder kommt nur die nächste Forderung?","coreRule":"⚡ Eine gute Nachfrage knüpft an deine Antwort an; ein Sealion stellt einfach die nächste Frage.","beleg":"Werkstück D.3.9 (Der Kipppunkt; Der Seelöwe im Wohnzimmer); Fn. gl-d-sealioning (Malki 2014, Wondermark Nr. 1062)","status":"entwurf","scenario":"Du hast unter einem Beitrag zur Wirkung eines Medikaments geschrieben, es habe in einer Studie die Beschwerden verringert. Auf Nachfrage hast du die Studie verlinkt und die Ergebnisse zusammengefasst. Daraufhin kommen vier Antworten.","kurz":"Legitim ist die Nachfrage, die mit deiner Antwort arbeitet: Sie knüpft an die Studie an und fragt gezielt nach einer Lücke, hier der Übertragbarkeit auf Kinder. Sealioning fordert dagegen nur immer Neues, ohne zu sagen, was am Gelieferten nicht genügt.","prueffrage":"Worauf in der verlinkten Studie bezieht sich jede der vier Antworten, und was verlangt sie von dir?","rueckmeldung":[{"option":0,"text":"Was „verringert“ genau heißt, könnte für sich eine berechtigte Frage sein. Hier folgt aber Forderung auf Forderung, ohne dass gesagt wird, was an der Quelle fehlt, und am Ende geht es um dein Verhalten statt um deine These."},{"option":2,"text":"Du hast die Studie schon verlinkt, die Frage nach einer Quelle geht also an deiner Antwort vorbei. Das freundliche „ich frage ja nur“ macht daraus keine Auseinandersetzung mit dem Beleg, sondern setzt dich unter Druck, weiter zu antworten."},{"option":3,"text":"Hier steht nicht deine These im Mittelpunkt, sondern dein Verhalten: Wer nicht endlos antwortet, soll dastehen, als hätte er nichts zu bieten. Zur Studie sagt der Beitrag nichts, und mit einem Beleg lässt sich die Frage nicht beantworten."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3"},{"id":"qx-d2-027","clusterId":"D","werkstueckRef":"D.3.9","stufe":4,"question":"Wie reagierst du am besten?","scenario":"Eine Verwandte fragt zu jeder deiner Aussagen „nur mal nach“, erkennt nie etwas an und erzählt hinterher, du seist gereizt gewesen. Du hast schon drei ihrer Fragen mit Belegen beantwortet. Auf keine Antwort ist sie eingegangen: Sie hat weder zugestimmt noch widersprochen noch etwas an ihrer Sicht geändert, sondern jedes Mal die nächste Frage gestellt.","options":["Weiter jede Frage ausführlich beantworten, weil jede unbeantwortete Frage in der Wahrnehmung der anderen als verlorener Punkt zählt.","Ihre Behauptungen im gleichen Umfang hinterfragen, weil so die Beweislast auf beide Seiten verteilt wird und sie selbst Belege liefern muss.","Aussprechen, dass sie auf keine Antwort eingegangen ist, und das Gespräch beenden, weil ein Austausch ohne Gegenseitigkeit kein echtes Gespräch mehr ist.","Ihr eine feste Zahl von Fragen pro Treffen zugestehen, weil so der Aufwand für beide Seiten gerecht begrenzt bleibt."],"correctIndex":2,"explanation":"Wer eine Behauptung belegt hat, hat seine Pflicht erfüllt. Weitere Belege schuldest du erst, wenn dein Gegenüber mit dem Beleg gearbeitet hat: ihn prüft, ihm widerspricht, zustimmt oder benennt, was ihn noch nicht überzeugt. Hier kommt auf jede Antwort nur die nächste Frage, bei geringem Aufwand für sie und hohem für dich. Das Ziel ist dann nicht Erkenntnis, sondern Erschöpfung, und wer irgendwann die Geduld verliert, steht als der Unfreundliche da. Weiter jede Frage zu beantworten wäre der Denkfehler, jede Frage verdiene eine Antwort und jede offene Frage sei ein verlorener Punkt. Gegenfragen und ein festes Fragenkontingent ändern nichts daran, dass deine Verwandte nicht mit den Belegen arbeitet; die Grenze ziehst du, wenn das ausbleibt. Ein Gespräch zu beenden, das keines ist, ist kein Rückzug, sondern ein begründetes Urteil über den Gesprächsverlauf.","coreRule":"⚡ Du schuldest Belege einmal, nicht endlos.","beleg":"Werkstück D.3.9 (Kontext & Tiefe, „Die Asymmetrie des Aufwands“; Anti-Denkmuster, „Bekämpfter Fehler“, „Der Ringrichter“ und Skript 2; Anwendung & Relevanz, „Familie und Freundeskreis“), Fußnote gl-d-sealioning (Malki 2014; Johnson 2017)","status":"entwurf","kurz":"Wer Belege gegeben hat, hat seine Pflicht erfüllt; weitere schuldest du erst, wenn sie mit ihnen arbeitet. Folgt auf jede Antwort nur die nächste Frage, darfst du das benennen und aufhören, statt jede offene Frage für einen verlorenen Punkt zu halten.","prueffrage":"Wie viel Mühe hat sie jede ihrer Fragen gekostet, und wie viel Mühe hat dich jede deiner Antworten gekostet?","rueckmeldung":[{"option":0,"text":"Jede Frage zu beantworten wirkt höflich, und Schweigen kann tatsächlich wie ein verlorener Punkt aussehen. Doch kein Punktestand entscheidet hier, sondern ob sie mit deinen Belegen arbeitet, und das tut sie nicht: Der Aufwand liegt allein bei dir."},{"option":1,"text":"Gegenfragen wirken fair, denn wer etwas behauptet, schuldet Belege. Am Kern ändern sie aber nichts: Sie arbeitet nicht mit deinen Belegen, und ein Hin und Her aus Fragen macht daraus noch kein Gespräch."},{"option":3,"text":"Ein Kontingent begrenzt den Aufwand und klingt gerecht. Es lässt aber den Kern bestehen: Auch innerhalb der erlaubten Fragen würde sie nicht auf deine Antworten eingehen, und dann ist die Zahl der Fragen weniger entscheidend als die fehlende Gegenseitigkeit."}],"familie":"kraefte-und-ausstieg","fertigkeit":"F3"},{"id":"qx-d2-028","clusterId":"D","werkstueckRef":"D.3.9","stufe":3,"question":"Warum trifft die Antwort der Nutzerin den Kern dieser Äußerung?","scenario":"Unter einem Beitrag über ein neues Impfprogramm schreibt jemand: „Ist es nicht seltsam, dass genau jetzt so viele Menschen krank werden? Ich frage ja nur.“ Eine Quelle oder Zahl nennt die Person nicht. Eine andere Nutzerin antwortet: „Das ist keine Frage, das ist eine Behauptung.“","options":["Die Frage unterstellt etwas, ohne es zu belegen, und der Fragende kann sich bei Widerspruch darauf zurückziehen, er habe ja nichts behauptet.","Jede Frage, auf die der Fragende die Antwort schon zu kennen glaubt, ist unaufrichtig und darf deshalb unbeantwortet bleiben.","Wer eine Frage stellt, ohne vorher selbst recherchiert zu haben, verliert das Recht, eine Antwort zu verlangen.","Eine Frage mit Auslassungspunkten oder Ausrufezeichen ist rhetorisch und damit nie eine echte Frage."],"correctIndex":0,"explanation":"Die Äußerung ist grammatisch eine Frage, legt aber eine Behauptung nahe: einen Zusammenhang zwischen dem Impfprogramm und den Erkrankungen. Solche Fragen sind verkleidete Behauptungen („Ist es nicht seltsam, dass …?“): Sie lassen sich streuen, ohne belegt werden zu müssen. Der Fragende kann sich bei Widerspruch darauf zurückziehen, er habe ja nur gefragt. Wer so antwortet, wie die Nutzerin es tut, legt die versteckte Behauptung frei, und erst dann lässt sie sich prüfen: Was genau wird nahegelegt, und wofür gibt es Belege? Ein ehrlicher Fragender arbeitet dagegen mit der Antwort: Er prüft sie, widerspricht ihr oder benennt, was ihn noch nicht überzeugt.","coreRule":"⚡ Prüfe bei jeder Frage, welche Behauptung sie mitführt, und wer diese Behauptung belegen müsste.","beleg":"Werkstück D.3.9 (Kontext & Tiefe, letzter Absatz, letzter Satz „Ein Verwandter ist das ‚Ich stelle doch nur Fragen‘ …“)","status":"entwurf","kurz":"Die Äußerung ist grammatisch eine Frage, legt aber einen Zusammenhang zwischen Impfprogramm und Erkrankungen nahe, ohne ihn zu belegen. Bei Widerspruch bleibt der Rückzug auf „ich habe ja nur gefragt“. Erst wer die versteckte Behauptung freilegt, kann sie prüfen.","prueffrage":"Würde sich an der Wirkung des Beitrags etwas ändern, wenn derselbe Satz ohne Fragezeichen dastünde?","rueckmeldung":[{"option":1,"text":"Dass jemand die Antwort schon zu kennen glaubt, macht eine Frage noch nicht unaufrichtig. Hier kommt etwas anderes hinzu: Ein bestimmter Zusammenhang wird nahegelegt, aber nie ausgesprochen. Das Freilegen dient der Prüfung, nicht dem Wegwischen der Frage."},{"option":2,"text":"Ob jemand vorher recherchiert hat, ist eine andere Frage als die nach der Form der Äußerung. Eine Antwort zu verlangen, setzt keine Recherche voraus. Das Problem liegt hier darin, dass ein nahegelegter Zusammenhang als Frage getarnt wird und so unbelegt bleiben kann."},{"option":3,"text":"Zeichensetzung entscheidet nicht darüber, ob eine Frage echt ist; es kommt darauf an, was die Äußerung nahelegt. Hier stehen weder Auslassungspunkte noch ein Ausrufezeichen, und trotzdem steckt hinter der Frageform eine Behauptung."}],"familie":"beweislast-klaeren","fertigkeit":"F1"},{"id":"qx-d2-029","clusterId":"D","werkstueckRef":"D.4.1","stufe":1,"question":"Welche Rückfrage prüft die Behauptung am besten?","scenario":"Auf der Webseite einer Praxis steht: „Unsere Behandlung löst Blockaden im Energie-Fluss und bringt die Schwingung Ihres Körpers zurück in die Harmonie. Spüren können das allerdings nur besonders sensitive Menschen; technische Geräte registrieren es nicht.“ Eine Freundin überlegt, dafür 400 Euro auszugeben.","options":["„In welcher Einheit misst du diese Energie, und mit welchem Instrument kann man sie auch ohne besonders sensitive Menschen nachweisen?“","„Wie viele Jahre gibt es diese Praxis schon, und wie viele Kundinnen und Kunden hatte sie bisher insgesamt?“","„Gibt es Erfahrungsberichte zufriedener Kundinnen, die nach der Behandlung ein besseres Körpergefühl beschreiben?“","„Wie sehr stimmen Aussehen und Auftreten der Praxis mit dem überein, was du von seriösen Gesundheitsangeboten erwartest?“"],"correctIndex":0,"explanation":"In der Physik ist Energie eine klar definierte, messbare Größe: Man gibt sie in Joule oder Kilowattstunden an und kann sie mit Instrumenten nachweisen. Hier wird dasselbe Wort zur vagen Allzweck-Erklärung: Es gibt keine Einheit, kein Messgerät, und wahrnehmbar soll es nur für „Sensitive“ sein. Dadurch lässt sich die Behauptung nie widerlegen, denn jeder Misserfolg ließe sich mit mangelnder Sensitivität erklären. Die Frage nach Einheit und Instrument zwingt dazu, den Begriff messbar zu machen oder zuzugeben, dass er nur bildlich gemeint ist. Praxisalter, Erfahrungsberichte und Auftreten sagen nichts darüber, ob das behauptete Phänomen überhaupt existiert.","coreRule":"⚡ Frag bei „Energie“ und „Schwingung“ nach Einheit und Messgerät.","beleg":"Werkstück D.4.1 (Der kaputte Fernseher; Kontext & Tiefe)","status":"entwurf","kurz":"Energie ist in der Physik messbar, mit Einheit und Instrument. Fragst du danach, muss die Praxis den Begriff messbar machen oder zugeben, dass er nur bildlich gemeint ist. Mit „nur Sensitive spüren es“ ließe sich dagegen jeder Misserfolg wegerklären.","prueffrage":"Woran könnte man erkennen, dass die Behauptung falsch ist, wenn jeder Misserfolg erklärbar bleibt?","rueckmeldung":[{"option":1,"text":"Eine lange Betriebsdauer und viele Kundinnen und Kunden wirken vertrauenswürdig, als hätte sich das Angebot bewährt. Sie zeigen aber nur, dass es Abnehmer findet, und nichts darüber, ob der behauptete Energie-Fluss überhaupt existiert."},{"option":2,"text":"Berichte von Zufriedenen sind echte Erfahrungen, und manche fühlen sich nach einer Behandlung tatsächlich besser. Das kann aber an Zuwendung, Erwartung oder dem natürlichen Verlauf liegen und sagt nichts darüber, ob ein Energie-Fluss existiert."},{"option":3,"text":"Ein seriöser Auftritt schafft Vertrauen, ist aber leicht herzustellen. Er beschreibt die Verpackung, nicht die Sache: Ob der behauptete Energie-Fluss existiert, lässt sich daran nicht ablesen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-d2-030","clusterId":"D","werkstueckRef":"D.4.1","stufe":2,"question":"Welche Rückfrage prüft diese Werbeaussage am wirksamsten?","scenario":"Auf einer Website steht: „Unser Kristall sendet starke Heilenergie aus und stellt die richtige Frequenz Ihrer Organe wieder her.“ Eine Messgröße oder Einheit wird nirgends genannt.","options":["„Wie viele Organe sind von dieser Wirkung betroffen, und wie lange hält sie an?“","„In welcher Einheit messen Sie diese Energie, und mit welchem Instrument weisen Sie sie nach?“","„Wie viel Watt gibt der Kristall ab, wenn er Energie für die Organe ausstrahlt?“","„Wie viele Menschen haben die Frequenz des Kristalls schon gespürt, und wie sensibel waren sie?“"],"correctIndex":1,"explanation":"Der Anbieter borgt sich Begriffe aus der Physik, ohne ihre messbare Bedeutung mitzuliefern. Energie lässt sich in Joule angeben, eine Strahlungsleistung in Watt, eine Frequenz in Hertz, und all das lässt sich mit Instrumenten nachweisen. Die Frage nach Einheit und Messgerät verlangt genau diesen Nachweis und zeigt, ob mehr als eine Metapher dahintersteckt. Die anderen Fragen übernehmen die Behauptung als gegeben: Selbst bei der Frage nach Watt kann der Anbieter eine beliebige Zahl nennen, solange niemand fragt, womit sie gemessen wurde. Und wer das „Spüren“ durch Menschen als Beleg gelten lässt, übergeht ein typisches Warnzeichen: Die Wirkung soll nur für „sensible“ Personen wahrnehmbar sein, nicht für Messgeräte.","coreRule":"⚡ Keine Einheit, kein Messgerät, keine Physik.","beleg":"Werkstück D.4.1 (Kontext & Tiefe, „Die wissenschaftliche Bedeutung“; Red Flags)","status":"entwurf","kurz":"Wer eine Messgröße, ihre Einheit und ein Nachweisinstrument verlangt, prüft, ob hinter den Physikbegriffen mehr steckt als eine Metapher. Der naheliegende Fehler ist, die Wirkung als gegeben zu nehmen und nur nach Details zu fragen.","prueffrage":"Welche Antwort könnte der Anbieter auf eine Frage geben, ohne dass sich irgendetwas an ihr überprüfen ließe?","rueckmeldung":[{"option":0,"text":"Umfang und Dauer einer Wirkung zu erfragen, ist bei einem belegten Effekt sinnvoll. Hier aber setzt die Frage voraus, dass es eine Wirkung gibt, und prüft gar nicht, ob die Behauptung überhaupt etwas Messbares meint."},{"option":2,"text":"Eine Zahl in Watt wirkt wie eine harte Prüfung. Doch die Frage unterstellt schon, dass der Kristall Energie abgibt; der Anbieter kann eine beliebige Zahl nennen, solange niemand nach dem Instrument fragt, das sie nachweist."},{"option":3,"text":"Berichte von Menschen, die etwas gespürt haben, klingen nach Erfahrung, sind aber kein Nachweis. Auf das Empfinden „sensibler“ Personen zu setzen, lässt gerade das Instrument außen vor, mit dem sich die Aussage überprüfen ließe."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-d2-031","clusterId":"D","werkstueckRef":"D.4.1","stufe":3,"question":"Welche dieser drei Situationen ist problematisch und warum?","options":["Situation 1, weil „Energie“ in der Physik fest definiert ist und jede andere Verwendung des Wortes Zuhörer in die Irre führt.","Situation 2, weil ein bildhaftes Wort als messbare Größe ausgegeben wird und daraus Diagnosen und teure Behandlungen folgen.","Situation 3, weil „Vibes“ auf eine Schwingung verweist, die sich ohne Messgerät nicht belegen lässt und daher unseriös ist.","Keine der drei Situationen, weil es überall nur um Sprache geht und Sprache grundsätzlich weder wahr noch falsch sein kann."],"correctIndex":1,"explanation":"Eine Metapher wie „gute Energie“ oder „gute Vibes“ beschreibt ein Gefühl und erhebt keinen Messanspruch. Sie schadet niemandem, solange alle verstehen, dass sie bildlich gemeint ist. Problematisch wird es, wenn dieselbe Redeweise als buchstäbliche, physikalische Realität auftritt: Dann müsste sich die behauptete „Frequenz“ in einer physikalischen Einheit und mit einem Instrument messen lassen. Hängen daran auch noch medizinische Diagnosen und teure Behandlungen, kann ein falscher Messanspruch echten Schaden anrichten. Entscheidend ist also nicht, ob ein Fachwort außerhalb der Fachsprache auftaucht, sondern ob aus einem Bild ein Messwert gemacht wird, auf den Entscheidungen mit Konsequenzen gebaut werden.","coreRule":"⚡ Eine Metapher ist harmlos, bis sie als Messwert verkauft wird.","beleg":"Werkstück D.4.1 (Der Kipppunkt)","status":"entwurf","scenario":"Drei Situationen:\\n(1) Eine Freundin betritt dein neues Wohnzimmer und sagt: „Der Raum hat eine richtig gute Energie.“\\n(2) Ein Anbieter bewirbt ein Gerät, das die „Schwingungsfrequenz“ deiner Organe misst, und erklärt daraus eine Diagnose samt teurem Behandlungsplan.\\n(3) Ein Kollege sagt nach einem gelungenen Workshop: „Die Vibes waren heute super.“","kurz":"Ein Gerät, das angeblich die „Schwingungsfrequenz“ der Organe misst, erhebt einen prüfbaren Messanspruch, und daran hängen Diagnose und Kosten. Wer jedes „Energie“ wörtlich nimmt, verwechselt Bild und Messanspruch; die beiden Redensarten sind harmlos.","prueffrage":"Was folgt in jeder der drei Situationen auf die Äußerung?","rueckmeldung":[{"option":0,"text":"Dass „Energie“ in der Physik fest definiert ist, stimmt. Im Wohnzimmer erhebt das Wort aber keinen Messanspruch, sondern beschreibt ein Gefühl, und das führt niemanden in die Irre, solange alle es als Bild verstehen."},{"option":2,"text":"Eine behauptete physikalische Schwingung müsste sich tatsächlich messen lassen. Der Kollege behauptet aber gar keine, er beschreibt die Stimmung. Wer bildhafte Rede wie eine Messbehauptung behandelt, hält sie zu Unrecht für unseriös."},{"option":3,"text":"Ein Gefühlsurteil wie „gute Vibes“ ist keine Aussage, die man widerlegen müsste. Sprache kann aber auch Tatsachen behaupten, etwa eine messbare Frequenz der Organe. Solche Behauptungen sind prüfbar und können bei falscher Grundlage echten Schaden anrichten."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-d2-032","clusterId":"D","werkstueckRef":"D.4.1","stufe":4,"question":"Ein Anbieter wirbt: „Unser Gerät misst die Frequenzen deiner Organe und deckt Disharmonien auf.“ Du darfst das Gerät aufschrauben und die Messtechnik prüfen. Was findest du bei einem Gerät, dessen Werbeversprechen sich nur als Kundentäuschung erklären lässt?","options":["Eine einfache Schaltung, die die elektrische Leitfähigkeit der Haut misst, ohne irgendetwas über einzelne Organe zu erfassen.","Einen empfindlichen Sensor, der die elektromagnetischen Eigenschwingungen einzelner Organe aufnimmt und rechnerisch trennt.","Einen Frequenzgenerator, der Schwingungen in den Körper sendet und die Reaktion einzelner Organe darauf registriert.","Ein Messgerät für Herzschlag und Hirnströme, das deren Frequenzen aufzeichnet und auffällige Rhythmen anzeigt."],"correctIndex":0,"explanation":"Hinter dem Wort „Frequenz“ steckt hier keine Organmessung. Bioresonanzgeräte bestehen im Wesentlichen aus einer Schaltung, die die Leitfähigkeit der Haut misst (Ernst 2023), und eine Hautleitfähigkeit sagt nichts über einzelne Organe; „Organfrequenzen“ und „Disharmonien“ sind damit keine Messwerte, sondern Deutung. Die übrigen Funde würden tatsächlich etwas an Organen erfassen und das Versprechen zumindest teilweise einlösen, wären also keine bloße Täuschung. Die Prüffrage lautet immer: Was misst das Gerät tatsächlich, in welcher Einheit, mit welchem Sensor, und wie wurde geprüft, dass der Messwert zum behaupteten Organ gehört? Ein bloß geliehenes Wort wie „Frequenz“ verleiht dem Gerät nur den Anschein von Wissenschaft.","coreRule":"⚡ Frag, was das Gerät tatsächlich misst, nicht, was der Prospekt behauptet.","beleg":"Werkstück D.4.1 (Anwendung & Relevanz, „In der Pseudomedizin“); Fn. gl-d-bioresonanz (Ernst 2023, Abschn. 13.4, S. 120)","status":"entwurf","scenario":"","kurz":"Bei solchen Geräten steckt hinter „Frequenz“ im Wesentlichen eine Schaltung für die Hautleitfähigkeit, und die sagt nichts über einzelne Organe. Der Fehler: Ein technisches Wort wird für eine Messung gehalten, obwohl „Organfrequenz“ und „Disharmonie“ nur Deutung sind.","prueffrage":"Welche Größe zeigt das Gerät an, in welcher Einheit, und wie wurde belegt, dass der Wert zu einem bestimmten Organ gehört?","rueckmeldung":[{"option":1,"text":"Ein empfindlicher Sensor für Organschwingungen klingt nach dem Werbeversprechen. Gerade deshalb passt er nicht: Ein Gerät, das Signale einzelner Organe tatsächlich aufnimmt und trennt, würde das Versprechen einlösen und wäre keine bloße Täuschung."},{"option":2,"text":"Senden und Empfangen wirkt wie echte Messtechnik, und Ultraschall arbeitet tatsächlich so. Ein Gerät, das damit einzelne Organe erfasst, wäre aber keine Täuschung; in Geräten wie dem beworbenen steckt im Wesentlichen eine Hautleitfähigkeitsschaltung."},{"option":3,"text":"Herzschlag und Hirnströme sind echte Frequenzen von Organen, und ein Gerät, das sie aufzeichnet, löst das Versprechen zumindest teilweise ein. Täuschung liegt dort vor, wo die Technik gar nichts über Organe erfassen kann."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-d2-033","clusterId":"D","werkstueckRef":"D.4.2","stufe":1,"question":"Welche Frage prüft die Behauptung des Verkäufers am besten?","scenario":"Ein Verkäufer preist einen rostigen Kleinwagen an: „Das ist ein Quanten-Auto. Denk mit deinem Quantenbewusstsein an dein Ziel, dann kollabiert die Wahrscheinlichkeitswelle des Motors zu deinen Gunsten.“","options":["Welche von Fachleuten geprüfte Messung zeigt, dass so ein Quanteneffekt bei einem Auto wirkt?","Wie viele frühere Kunden waren nach dem Kauf mit dem Wagen zufrieden und fahren ihn noch?","Welche Ausbildung hat der Verkäufer und wie lange arbeitet er schon im Autohandel?","Wie hoch ist der Preis im Vergleich zu anderen gebrauchten Kleinwagen derselben Marke?"],"correctIndex":0,"explanation":"Der Verkäufer benutzt Begriffe aus der Quantenphysik („Wahrscheinlichkeitswelle“, „Kollaps“). Deren Gesetze gelten zwar auch für große Objekte, doch Überlagerungen zerfallen bei einem Auto durch die ständige Wechselwirkung mit der Umgebung so schnell, dass man sie nicht beobachten kann (Dekohärenz); sichtbar werden sie nur an gut abgeschirmten Systemen wie einzelnen Teilchen, Atomen oder Molekülen. Die Quantenbegriffe dienen hier als Wissenschafts-Anstrich: Weil Laien die echte Quantenphysik kaum nachprüfen können, lässt sich ihr Vokabular als Schutzschild gegen Kritik missbrauchen. Wer die Behauptung prüfen will, muss deshalb nach einem Nachweis für den behaupteten Effekt fragen. Fragen nach Zufriedenheit, Erfahrung oder Preis lassen offen, ob die Behauptung überhaupt stimmen kann.","coreRule":"⚡ Wenn ein Alltagsding „Quanten“ im Namen trägt, frag nach der Studie, die den Quanteneffekt messbar nachweist.","beleg":"Werkstück D.4.2 (Der erleuchtete Autoverkäufer; Kernidee)","status":"entwurf","kurz":"Wer den „Quanteneffekt“ prüfen will, muss nach einem Nachweis fragen. Quantenbegriffe wirken wissenschaftlich, doch bei einem Auto zerfallen Überlagerungen durch die Umgebung so schnell, dass man sie nie beobachten kann (Dekohärenz). Der Fachjargon täuscht Substanz vor.","prueffrage":"Was müsste am Auto anders ablaufen, wenn du an dein Ziel denkst, als wenn du es nicht tust?","rueckmeldung":[{"option":1,"text":"Zufriedene Kunden sagen etwas darüber, ob der Wagen taugt, doch nichts darüber, ob ein Quanteneffekt im Spiel ist. Die Behauptung selbst bleibt damit ungeprüft."},{"option":2,"text":"Ausbildung und Berufsjahre klingen nach Verlässlichkeit, bleiben aber ein Blick auf den Sprecher. Ob der Effekt existiert, entscheidet sich nicht an seinem Lebenslauf, denn auch Erfahrene können Unsinn behaupten."},{"option":3,"text":"Ein Preisvergleich ist beim Autokauf vernünftig, trifft aber nicht die Behauptung. Ein günstiger Preis macht aus dem Wagen kein Quanten-Auto und sagt nichts darüber, ob es den Effekt gibt."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-d2-034","clusterId":"D","werkstueckRef":"D.4.2","stufe":2,"question":"Welche Gegenfrage prüft die Behauptung des Coaches am besten?","scenario":"Ein Coach sagt, durch „Quantenverschränkung“ und die Kraft deiner Absicht könnest du deine Krankheit „zum Kollabieren bringen“. Du willst herausfinden, ob an der Behauptung etwas dran ist.","options":["Welche Fachgesellschaft hat dich als Quantenheiler zertifiziert, und wie lange arbeitest du schon in diesem Beruf?","Welche Studie zeigt, dass ein solcher Quanteneffekt im menschlichen Körper eine messbare Wirkung hat, und wo ist sie veröffentlicht?","Welche Rechnung zur Schrödinger-Gleichung für ein Elektron kannst du vorführen, und was zeigt sie über dein Wissen?","Welche Erfahrungsberichte früherer Klienten sprechen für deine Methode, und wo kann ich ihre Bewertungen nachlesen?"],"correctIndex":1,"explanation":"Geprüft werden muss die Behauptung, nicht die Person. Quanteneffekte wie Verschränkung oder Überlagerung sind real, lassen sich aber nur an gut abgeschirmten Systemen beobachten. In größeren Systemen zerfallen die Überlagerungen durch die ständige Wechselwirkung mit der Umgebung so schnell, dass man sie nicht beobachten kann (Dekohärenz). Ob so ein Effekt im menschlichen Körper etwas heilt, lässt sich deshalb nur mit einer begutachteten Studie am konkreten System belegen. Für Heilversprechen dieser Art gibt es eine solche Studie nicht. Ein Zertifikat oder Berufsjahre helfen nicht weiter: Eine Quelle, die nur ein spiritueller Guru oder Coach ist, liefert keinen Nachweis am System. Eine Rechenvorführung zeigt ebenfalls nicht, ob die Behauptung zutrifft. Erfahrungsberichte beantworten die Kernfrage nicht, ob ein Quanteneffekt im Körper eine messbare Wirkung hat. Sie liefern keinen Nachweis am konkreten System.","coreRule":"⚡ Verlang den Nachweis am konkreten System, nicht den Titel der Person.","beleg":"Werkstück D.4.2 (Anti-Denkmuster, Aktivierungs-Frage)","status":"entwurf","kurz":"Ob ein Quanteneffekt im Körper etwas heilt, zeigt nur eine begutachtete Studie am konkreten System, und für solche Heilversprechen gibt es keine. Der naheliegende Fehler ist, die Person zu prüfen statt die Behauptung.","prueffrage":"Woran ließe sich von außen erkennen, ob deine Absicht tatsächlich etwas an der Krankheit verändert hat?","rueckmeldung":[{"option":0,"text":"Nach der Qualifikation zu fragen, klingt sachlich, denn Fachwissen kann ein Hinweis sein. Es prüft aber die Person und nicht die Behauptung: Ein Zertifikat oder Berufsjahre belegen nicht, dass der Effekt im Körper existiert."},{"option":2,"text":"Quantenphysik hat tatsächlich mit Rechnungen zu tun, deshalb liegt diese Probe nahe. Sie zeigt aber nur, was jemand rechnen kann. Ob im Körper ein Quanteneffekt eine Krankheit beeinflusst, sagt eine Rechnung für ein einzelnes Elektron nicht."},{"option":3,"text":"Erfahrungsberichte wirken greifbar, weil dort echte Menschen sprechen. Sie sind aber Einzelfälle ohne Vergleich und ohne Messung und zeigen nicht, ob ein Quanteneffekt im Körper messbar wirkt."}],"familie":"autoritaet-pruefen","fertigkeit":"F2"},{"id":"qx-d2-035","clusterId":"D","werkstueckRef":"D.4.2","stufe":3,"question":"Ein Esoterik-Coach sagt: „Quantenphysik gilt nur für Atome. Ein Fußball ist nie an zwei Orten gleichzeitig, also ist klar, dass Quantengesetze bei großen Objekten einfach aufhören. Meine Kunden brauchen sich um Quantenphysik im Alltag also keine Sorgen zu machen.“ Du willst ihm nicht nur die falsche Schlussfolgerung nachweisen, sondern auch erklären, warum der Ball sich trotzdem klassisch verhält. Welche Erklärung ist die sparsamste und zugleich sachlich haltbar?","options":["Quantengesetze enden bei einer bestimmten Größe; darüber gilt allein die klassische Physik, die Überlagerungen grundsätzlich verbietet.","Die Überlagerung besteht beim Ball dauerhaft fort, ist aber viel zu klein, um sie mit heutigen Geräten jemals messen zu können, und wirkt deshalb nicht.","Die Gesetze gelten auch für große Objekte, doch die Umgebung lässt die Überlagerung so schnell zerfallen, dass man sie nicht beobachten kann.","Der Beobachter erzwingt bei jedem Alltagsgegenstand durch sein Bewusstsein einen festen Ort, sobald er hinsieht und den Ball wahrnimmt."],"correctIndex":2,"explanation":"Die Quantenphysik beschränkt sich nicht auf das Subatomare: Überlagerung wurde schon an Molekülen aus rund 2.000 Atomen nachgewiesen (Fein u. a. 2019). Eine Grenze, an der die Gesetze enden, ist also nicht belegt. Dass der Ball trotzdem klassisch wirkt, erklärt die Dekohärenz: Große Objekte stehen ständig in Wechselwirkung mit ihrer Umgebung, wodurch ihre Überlagerungen so schnell zerfallen, dass man sie nicht beobachten kann. Dieselben Gesetze erzeugen also das klassische Verhalten. Die Erklärung kommt ohne Sonderregel für große Dinge aus und ist deshalb die sparsamste. Die Bewusstseins-Variante ist die esoterische Umdeutung des Beobachtereffekts und gilt als Pseudowissenschaft.","coreRule":"⚡ Wenn ein Effekt im Alltag fehlt, schließe nicht auf „Gesetz endet hier“. Frage, welcher Mechanismus ihn unbeobachtbar macht. Bei Quanteneffekten zerstört die Umgebung die Überlagerung großer Objekte so schnell, dass sie unbeobachtbar bleibt.","beleg":"Werkstück D.4.2 (Kontext & Tiefe, „Die wissenschaftliche Bedeutung“); Fn. gl-d-quanten (Fein u. a. 2019, Nature Physics 15), gl-d-dekohaerenz (Zurek 2003, Reviews of Modern Physics 75, S. 715–775)","status":"entwurf","scenario":"","kurz":"Die Gesetze gelten auch für große Objekte. Der Ball wirkt klassisch, weil seine Überlagerungen durch die ständige Wechselwirkung mit der Umgebung rasch zerfallen. Eine Größengrenze samt Sonderregel ist dafür unnötig.","prueffrage":"Wurde Überlagerung schon an Objekten nachgewiesen, die deutlich größer sind als einzelne Atome?","rueckmeldung":[{"option":0,"text":"Im Alltag verhalten sich große Dinge tatsächlich klassisch. Eine feste Größengrenze ist aber nicht belegt: Überlagerung wurde schon an Molekülen aus rund 2.000 Atomen nachgewiesen, und eine Sonderregel für Großes wäre unnötig aufwendig."},{"option":1,"text":"Richtig ist, dass die Gesetze auch beim Ball weitergelten. Die Überlagerung bleibt aber nicht bestehen und ist auch nicht bloß zu klein zum Messen. Sie zerfällt durch die Wechselwirkung mit der Umgebung so schnell, dass man sie nie beobachten kann."},{"option":3,"text":"Messung spielt in der Quantenphysik eine Rolle, doch Bewusstsein ist dafür nicht nötig. Der Zerfall der Überlagerung geschieht auch ohne Betrachter durch die Umgebung. Die Bewusstseins-Deutung ist eine esoterische Umdeutung und gilt als Pseudowissenschaft."}],"familie":"mechanismus-verlangen","fertigkeit":"F1"},{"id":"qx-d2-036","clusterId":"D","werkstueckRef":"D.4.2","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Eine Anbieterin von „Quantenheilung“ sagt: „Quantenphysik versteht kaum jemand richtig, du nicht und ich auch nicht ganz. Also kannst du nicht ausschließen, dass meine Deutung stimmt. Es könnte also wirken.“","options":["Aus dem Umstand, dass niemand etwas sicher ausschließen kann, wird abgeleitet, dass es plausibel sei; Nichtwissen gilt als Beleg.","Die Anbieterin greift den Kritiker als Person an, statt auf dessen Gründe einzugehen, und schränkt dadurch das Gespräch ein.","Die Anbieterin setzt die zu beweisende Behauptung bereits als Voraussetzung ein und dreht sich mit ihrer Begründung im Kreis.","Die Anbieterin beruft sich auf eine Fachautorität, die ihre Deutung nie bestätigt hat, und hält dadurch die Debatte offen."],"correctIndex":0,"explanation":"Der Schluss lautet: „Wir verstehen es nicht, also könnte meine Deutung wahr sein.“ Das ist ein Argument aus Unwissenheit. Aus Nichtwissen wird hier Plausibilität gemacht, obwohl Nichtwissen kein Beleg ist. Die Komplexität des Themas wird als Schutzschild gegen Kritik missbraucht. Wirkt etwas, muss sich das belegen lassen, etwa durch eine Studie, die an einem biologischen System eine messbare Wirkung zeigt. Die Schwierigkeit des Themas ersetzt diesen Beleg nicht. Zudem lassen sich Quanteneffekte nur an gut abgeschirmten, kleinen Systemen beobachten, weil die Umgebung Überlagerungen großer Objekte sehr schnell zerstört (Dekohärenz).","coreRule":"⚡ „Das kann man nicht widerlegen“ ist kein Beleg.","beleg":"Werkstück D.4.2 (Kontext & Tiefe, „Die pseudowissenschaftliche Umdeutung“; Verweis auf Werkstück B.11, Argument aus Unwissenheit)","status":"entwurf","kurz":"Dass niemand etwas ganz ausschließen kann, macht es nicht plausibel: Nichtwissen ist kein Beleg. Ein Wirkungsnachweis müsste messbar sein, etwa an einem biologischen System. Das schwierige Thema ersetzt ihn nicht, es schützt nur vor Kritik.","prueffrage":"Was ließe sich mit dem Satz „du kannst es nicht ausschließen“ sonst noch alles begründen?","rueckmeldung":[{"option":1,"text":"„Du nicht“ kann wie ein Seitenhieb klingen, doch die Anbieterin schließt sich mit „ich auch nicht ganz“ selbst ein und greift niemanden an. Fehlerhaft ist der Schluss vom allgemeinen Nichtverstehen auf Plausibilität."},{"option":2,"text":"Ein Kreis wäre es, wenn die Behauptung schon in ihrer Begründung steckte. Hier folgt „es könnte wirken“ aber aus dem Nichtverstehen. Die Begründung trägt nicht, sie läuft nur nicht im Kreis."},{"option":3,"text":"Eine Fachautorität nennt die Anbieterin nicht. Sie sagt nur, kaum jemand verstehe Quantenphysik richtig, und macht aus diesem Nichtwissen ein Argument für ihre Deutung."}],"familie":"widerlegung-benennen","fertigkeit":"F1"},{"id":"qx-d2-037","clusterId":"D","werkstueckRef":"D.4.3","stufe":1,"question":"Ein Händler sagt: „Unser Vitamin C ist rein natürlich, aus handgepflückten Kirschen, und deshalb besser für den Körper als die Tablette aus dem Labor.“ Beide Produkte enthalten dasselbe Molekül. Welche Erwiderung prüft die Behauptung am besten?","scenario":"Du stehst im Reformhaus. Der Händler zeigt dir zwei gleich aussehende Pillen: Pille A mit „natürlichem“ Vitamin C aus Acerolakirschen für den doppelten Preis, Pille B mit synthetischer Ascorbinsäure aus dem Labor. Auf beiden Packungen steht als Wirkstoff dasselbe Molekül, C₆H₈O₆.","options":["Wenn es dasselbe Molekül ist, kann der Körper keinen Unterschied erkennen; die Herkunft zeigt keine bessere Wirkung, dafür müsste er Studien zur Aufnahme vorlegen.","Wenn es dasselbe Molekül ist, wirkt die Laborversion besser, weil Stoffe aus dem Labor grundsätzlich wirksamer sind als natürliche.","Wenn es dasselbe Molekül ist, hängt die Wirkung davon ab, wie sorgfältig und ursprungsnah der Stoff gewonnen wurde, deshalb zählt die Herkunft.","Wenn es dasselbe Molekül ist, wirken beide gleich, sobald man sie zusammen mit etwas Natürlichem einnimmt, das sie angleicht."],"correctIndex":0,"explanation":"Der Händler schließt von der Herkunft („natürlich“) auf die Wirkung. Das ist ein Appell an die Natur. Ein Molekül ist durch seine Struktur bestimmt, nicht durch seinen Ursprung: Der Körper kann zwei identische Moleküle nicht unterscheiden. Eine bessere Wirkung müsste der Händler belegen, nicht behaupten. Das ist auch empirisch geprüft: Eine randomisierte Studie (Carr u. a. 2013) fand zwischen Vitamin C aus Kiwis und aus Tabletten keinen Unterschied in der Aufnahme. Auch die Laborversion ist bei identischem Molekül nicht besser: Reinheit und Dosierbarkeit können synthetische Wirkstoffe allgemein auszeichnen, erklären hier aber keinen Wirkunterschied. Was bleibt, ist der Preisaufschlag für ein Wort.","coreRule":"⚡ Gleiche Struktur, gleiche Wirkung: Die Herkunft eines Moleküls ist kein Qualitätsmerkmal; wer eine Überlegenheit behauptet, muss sie belegen.","beleg":"Werkstück D.4.3 (Der Vitamin-C-Test; Kontext & Tiefe); Fn. gl-d-vitc (Carr u. a. 2013, Nutrients 5(9), 3684–3695)","status":"entwurf","kurz":"Identische Moleküle kann der Körper nicht unterscheiden, deshalb sagt die Herkunft nichts über die Wirkung. Der Händler schließt von „natürlich“ auf „besser“; einen Vorteil müsste er belegen, etwa mit Studien zur Aufnahme.","prueffrage":"Was unterscheidet die beiden Pillen außer Herkunft und Preis?","rueckmeldung":[{"option":1,"text":"Wer „natürlich“ nicht für besser hält, vermutet leicht das Gegenteil. Das wäre aber derselbe Fehler mit umgekehrtem Vorzeichen: Bei identischem Molekül ist auch die Laborversion nicht wirksamer, Reinheit und Dosierbarkeit erklären hier keinen Unterschied."},{"option":2,"text":"Sorgfältige Gewinnung klingt nach Qualität, und bei vielen Produkten spielt sie eine Rolle. Die Wirkung eines Moleküls hängt aber an seiner Struktur und nicht an seinem Weg dorthin; der Körper erfährt die Herkunft nicht."},{"option":3,"text":"Dass beide gleich wirken, stimmt, aber nicht wegen eines Zusatzes. Der Schluss erfindet eine Bedingung, die niemand belegt hat, und tut so, als bräuchte es erst etwas „Natürliches“, damit gleiche Moleküle gleich wirken."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-d2-038","clusterId":"D","werkstueckRef":"D.4.3","stufe":2,"question":"Was ist an diesem Werbeversprechen im Kern fehlerhaft?","scenario":"Auf einem Shampoo steht: „Frei von Chemie – rein natürlich.“ Ein Kollege sagt: „Dann ist es bestimmt sanfter und sicherer als die Konkurrenz.“","options":["Es setzt „Chemie“ mit „schädlich“ und „natürlich“ mit „sicher“ gleich, obwohl alle Stoffe Chemie sind und die Herkunft nichts über die Sicherheit aussagt.","Es verschweigt, dass Shampoo ohne einen synthetisch hergestellten Stoff grundsätzlich nicht haltbar gemacht werden kann.","Es ist unproblematisch, solange die Inhaltsstoffe auf der Packung stehen, denn dann kann jeder selbst entscheiden, was er davon hält.","Es ist inhaltlich korrekt, da natürliche Inhaltsstoffe grundsätzlich ungefährlich sind, und der Slogan ist nur zu kurz formuliert."],"correctIndex":0,"explanation":"Alles ist Chemie: Ein Apfel ist ein Beutel voller Chemikalien, und auch Wasser (H₂O) ist Chemie. „Chemiefrei“ ist deshalb ein unmöglicher Zustand und als Eigenschaft eines Produkts bedeutungslos. Der Slogan arbeitet mit der Intuition, Natur sei gütig und das Labor kalt, und überspringt dabei die eigentlich entscheidenden Fragen: Welcher Stoff ist enthalten, in welcher Dosis, und was zeigen kontrollierte Studien zu Wirkung und Verträglichkeit? Die Herkunft eines Moleküls sagt darüber nichts. Ein identisches Molekül wirkt gleich, egal ob es aus einer Pflanze oder aus dem Labor stammt (bei Vitamin C aus Kiwis und aus Tabletten fand eine randomisierte Studie keinen Unterschied in der Aufnahme). Viele der giftigsten Substanzen der Welt sind „rein natürlich“, und synthetische Versionen sind oft reiner und genauer dosierbar. Die Werbung erzeugt also eine Präferenz, noch bevor ein einziges Faktum zur Sicherheit genannt wurde.","coreRule":"⚡ „Chemiefrei“ gibt es nicht: Frag nach Stoff, Dosis und Studie – nicht nach der Herkunft.","beleg":"Werkstück D.4.3 (Kontext & Tiefe, „Alles ist chemisch“; Anwendung & Relevanz, Lebensmittel- und Kosmetikindustrie; Red Flags; Anti-Denkmuster)","status":"entwurf","kurz":"Alles ist Chemie, sogar Wasser; „chemiefrei“ beschreibt also nichts. Die Herkunft eines Stoffes sagt zudem nichts über seine Sicherheit: Entscheidend sind Stoff, Menge und Studienlage, nicht ob er aus Pflanze oder Labor stammt.","prueffrage":"Was erfährst du aus „Frei von Chemie – rein natürlich“ über die Inhaltsstoffe des Shampoos?","rueckmeldung":[{"option":1,"text":"Der Vorwurf, der Slogan verschweige etwas, wirkt wie ein guter Einwand. Doch die Behauptung ist zu absolut, denn Haltbarkeit lässt sich auch anders erreichen. Der Kern liegt woanders: „Frei von Chemie“ beschreibt gar keine mögliche Eigenschaft."},{"option":2,"text":"Eine Inhaltsliste hilft, informiert zu entscheiden. Der Slogan wirbt aber schon vorher mit etwas Unmöglichem, „Frei von Chemie“, und lässt „natürlich“ als sicher erscheinen. Diesen Fehler behebt auch eine vollständige Inhaltsliste nicht."},{"option":3,"text":"Natürliche Stoffe können ebenso schädlich sein; viele der giftigsten Substanzen der Welt sind rein natürlich. Und der Slogan ist nicht bloß zu kurz: „Frei von Chemie“ ist inhaltlich bedeutungslos, weil alles Chemie ist."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-d2-039","clusterId":"D","werkstueckRef":"D.4.3","stufe":3,"question":"Wo kippt eine harmlose Vorliebe für „Natürliches“ in eine echte Gefahr?","options":["Eine Person kauft bewusst weniger verarbeitete Lebensmittel, weil sie ihr besser schmecken und weil sie Zutatenlisten mit vielen Zusatzstoffen meidet.","Eine Person lehnt ein ärztlich empfohlenes, gut untersuchtes Medikament ab, weil es im Labor hergestellt wurde und „unnatürlich“ sei, und setzt stattdessen auf einen Kräutertee.","Eine Person greift zu einer Hautcreme mit Pflanzenextrakten, weil sie die Verpackung ansprechender findet als die der Konkurrenz.","Eine Person nimmt zusätzlich zur ärztlich verordneten Behandlung ein pflanzliches Mittel, weil sie sich damit besser fühlt und ihr Arzt davon weiß."],"correctIndex":1,"explanation":"Eine Vorliebe für weniger Verarbeitetes oder Pflanzliches bleibt harmlos, solange sie eine Geschmacks- oder Stilfrage ist. Gefährlich wird sie, wenn die Herkunft zum Maßstab wird und ein wirksames, gut geprüftes Mittel nur deshalb verworfen wird, weil es synthetisch ist. Ob ein Wirkstoff hilft oder schadet, hängt von Struktur, Dosis und belegter Wirkung ab, nicht davon, ob er im Labor oder in einer Pflanze entstand. Vitamin C aus Kiwis und aus Tabletten wird gleich gut aufgenommen. Wer aus „Natürlichkeit“ auf Sicherheit und aus „Labor“ auf Gefahr schließt, gibt im Ernstfall den Nutzen eines Medikaments, eines Impfstoffs oder eines lebensrettenden Zusatzstoffs auf. In den übrigen Fällen geht es um Geschmack, Verpackung oder eine Ergänzung in Absprache mit dem Arzt. Dort wird keine wirksame Behandlung verworfen.","coreRule":"⚡ Eine Vorliebe für Natürliches ist erlaubt; sie wird gefährlich, wenn sie wirksame Mittel verwirft.","beleg":"Werkstück D.4.3 (Der Kipppunkt)","status":"entwurf","scenario":"Vier Leute erzählen, wie sie es mit „natürlich“ und „synthetisch“ halten.","quote":"","quoteLabel":"","kurz":"Gefährlich wird die Vorliebe, wenn die Herkunft zum Maßstab wird und ein gut geprüftes Medikament nur abgelehnt wird, weil es synthetisch ist. Ob ein Stoff hilft oder schadet, hängt von Wirkstoff und Dosis ab, nicht davon, ob er aus Labor oder Pflanze stammt.","prueffrage":"Was steht für jede Person auf dem Spiel, falls sich ihre Wahl als falsch erweist?","rueckmeldung":[{"option":0,"text":"Weniger Verarbeitetes zu bevorzugen und Zutatenlisten mit vielen Zusatzstoffen zu meiden, ist eine Geschmacks- und Stilfrage. Dabei wird keine wirksame Behandlung aufgegeben und auf keine nötige Hilfe verzichtet."},{"option":2,"text":"Eine Creme wegen der Verpackung zu wählen, ist eine reine Geschmacksentscheidung ohne Urteil über Gesundheit. Es wird nichts abgelehnt, was helfen könnte; die Herkunft ist hier nicht der Maßstab."},{"option":3,"text":"Ein pflanzliches Mittel neben einer Therapie wirkt riskant, und Wechselwirkungen kommen tatsächlich vor. Hier läuft die verordnete Behandlung aber weiter, und der Arzt weiß davon. Verworfen wird keine wirksame Therapie."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4"},{"id":"qx-d2-040","clusterId":"D","werkstueckRef":"D.4.3","stufe":4,"question":"Welche Erklärung ist die sparsamste und lässt sich zugleich am besten prüfen?","scenario":"In einem Video heißt es, Flugzeuge versprühten über uns „Chemtrails“: Die langen weißen Streifen am Himmel seien künstliche Gifte, mit denen uns jemand heimlich vergifte. Als „Beweis“ wird gezeigt, dass die Streifen manchmal lange stehen bleiben und sich ausbreiten.","options":["Die Streifen sind Eiskristalle aus dem Wasserdampf der Triebwerksabgase. Dafür braucht es weder einen Zusatzstoff noch eine geheime Absicht.","Die Streifen sind Eiskristalle aus Triebwerksabgasen, vermischt mit einem Zusatzstoff. Ob er wirkt, lässt sich erst bei einer Probe vom Boden sagen.","Die Streifen sind je nach Flugroute mal harmlos, mal giftig. Wer die Route kennt, kann beides unterscheiden, auch wenn es von unten gleich aussieht.","Die Streifen sind ein Hinweis auf Eingriffe in die Atmosphäre. Dass es dazu keine offenen Belege gibt, zeigt nur, wie gut die Sache abgeschirmt wird."],"correctIndex":0,"explanation":"Die sparsamste Erklärung kommt mit bekannten Vorgängen aus: Die Streifen sind gewöhnliche Kondensstreifen, also Eiskristalle aus dem Wasserdampf der Triebwerksabgase. Wie lange sie stehen bleiben und ob sie sich ausbreiten, hängt von Feuchte und Temperatur der Luft in Flughöhe ab: In sehr feuchter, kalter Luft halten sie sich lange, in trockener verschwinden sie rasch. Die anderen Deutungen führen unbelegte Stoffe oder Absichten ein, ohne dass die Beobachtungen sie verlangen. Die Deutung, fehlende Belege bestätigten die Abschirmung, ist zudem so gebaut, dass sie sich nie widerlegen lässt. Wer ein Gift behauptet, muss es belegen.","coreRule":"⚡ „Künstlich“ ist kein Beweis für „giftig“: Frage nach Stoff, Menge und Beleg, nicht nach der Herkunft.","beleg":"Werkstück D.4.3 (Anwendung & Relevanz, „Bei Verschwörungsmythen (Chemtrails etc.)“)","status":"entwurf","kurz":"Kondensstreifen sind Eiskristalle aus dem Wasserdampf der Abgase; wie lange sie stehen und sich ausbreiten, hängt von Feuchte und Temperatur der Luft in Flughöhe ab. Ein Gift braucht es dafür nicht, und wer eines behauptet, muss es belegen.","prueffrage":"Was genau soll in den Streifen stecken, und welche Belege gibt es dafür außer ihrem Anblick?","rueckmeldung":[{"option":1,"text":"Eine Probe zu nehmen, wirkt wie eine Prüfung. Doch der Zusatzstoff wird ohne jeden Anlass angenommen, denn die Beobachtungen verlangen ihn nicht. Das macht die Erklärung aufwendiger, nicht besser."},{"option":2,"text":"Die Flugroute als Merkmal klingt nach Insiderwissen. Doch wenn harmlose und giftige Streifen von unten gleich aussehen, lässt sich die Unterscheidung kaum nachprüfen, und sie führt ein Gift ein, das keine Beobachtung verlangt."},{"option":3,"text":"Hier wird das Fehlen von Belegen selbst zum Beleg umgedeutet. Eine Deutung, die jeden Gegenbefund als Beweis für die Abschirmung liest, kann sich nie widerlegen lassen und sagt deshalb nichts Prüfbares."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-d2-041","clusterId":"D","werkstueckRef":"D.4.4","stufe":1,"question":"Wie lässt sich der Unterschied zwischen den beiden Ansätzen am besten beschreiben, obwohl beide „ganzheitlich“ sagen?","scenario":"Du hast chronische Kopfschmerzen. Arzt A untersucht dich gründlich, verschreibt ein Medikament und fragt auch nach Stress, Schlaf und Ernährung. Arzt B untersucht dich nicht körperlich, spricht von einer „Blockade im Energie-Meridian“ und verkauft dir Kristalle. Beide nennen ihren Ansatz „ganzheitlich“.","options":["Arzt A erweitert die überprüfbare Medizin um Lebensstil und Psyche; Arzt B ersetzt sie durch Konzepte, die sich nicht messen lassen.","Arzt A behandelt nur das Symptom, während Arzt B den ganzen Menschen betrachtet und damit als Einziger wirklich ganzheitlich arbeitet.","Beide arbeiten gleichermaßen ganzheitlich; Arzt B ist nur weniger genau und könnte seine Methoden durch Messungen ergänzen.","Arzt A arbeitet ganzheitlich, weil er ein Medikament verschreibt; Arzt B nicht, weil er Körper und Geist als getrennte Bereiche behandelt."],"correctIndex":0,"explanation":"Dass Körper, Geist und Umwelt zusammenhängen, ist unstrittig und in der Medizin etabliert: Die Psychoneuroimmunologie erforscht zum Beispiel, wie Stress das Immunsystem beeinflusst. Arzt A nutzt diesen Gedanken, um eine geprüfte Behandlung zu ergänzen. Arzt B nutzt dieselbe unstrittige Aussage als Eintrittskarte für Diagnosen und Behandlungen, die sich nicht überprüfen lassen. Dass das Wort gleich klingt, sagt nichts darüber, was damit verkauft wird: Wer dem Grundsatz „Körper und Geist sind verbunden“ zustimmt, hat damit noch nicht Kristalle oder Meridian-Blockaden als wirksam anerkannt.","coreRule":"⚡ „Ganzheitlich“ kann ergänzen oder ersetzen: Prüf, was damit verkauft wird.","beleg":"Werkstück D.4.4 (Die zwei Ärzte; Kontext & Tiefe; Anwendung & Relevanz)","status":"entwurf","kurz":"Beide berufen sich auf den unstrittigen Gedanken, dass Körper und Psyche zusammenhängen. Arzt A ergänzt damit geprüfte Medizin, Arzt B verkauft Unüberprüfbares. Das gleiche Wort sagt nichts darüber, was dahintersteckt.","prueffrage":"Was hat jeder der beiden Ärzte getan, bevor er seine Behandlung festgelegt hat?","rueckmeldung":[{"option":1,"text":"Ein Medikament wirkt schnell wie reine Symptombehandlung. Doch Arzt A untersucht gründlich und fragt nach Stress, Schlaf und Ernährung, während Arzt B nicht einmal körperlich untersucht und den Menschen damit kaum umfassender betrachtet."},{"option":2,"text":"Weil beide dasselbe Wort benutzen, wirken die Ansätze gleichwertig. Arzt B ergänzt aber keine geprüfte Medizin, er ersetzt sie durch Konzepte wie Meridian-Blockaden, die sich nicht messen lassen. Das ist kein Unterschied im Grad der Genauigkeit."},{"option":3,"text":"Ein Medikament macht eine Behandlung nicht ganzheitlich; bei Arzt A zählt, dass er auch Stress, Schlaf und Ernährung einbezieht. Arzt B trennt Körper und Geist gar nicht, sein Problem ist die fehlende Überprüfbarkeit."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4"},{"id":"qx-d2-042","clusterId":"D","werkstueckRef":"D.4.4","stufe":2,"question":"Was ist an dieser Abfolge von Aussage und Schlussfolgerung fehlerhaft?","scenario":"Auf einer Website steht: „Wir betrachten den ganzen Menschen, denn Körper und Geist sind untrennbar verbunden. Deshalb gleichen wir mit unserer Aura-Reinigung Ihre Energiefelder aus.“","options":["Die erste Aussage ist unstrittig. Weil ihr niemand widerspricht, wird stillschweigend auch die darauf aufbauende, unbewiesene Methode als akzeptiert behandelt.","Die erste Aussage zeichnet eine übertriebene Karikatur der Gegenseite, die sich leicht widerlegen lässt und die eigene Methode dadurch stärker wirken lässt.","Die erste Aussage beruft sich auf anerkannte medizinische Autoritäten, und die Fachsprache wird dann auf fremde Verfahren übertragen, ohne deren Wirkung zu belegen.","Die erste Aussage stellt zwei Wege als einzige Möglichkeiten dar, nämlich ganzheitlich oder nur Symptome behandeln, und verschweigt weitere Alternativen."],"correctIndex":0,"explanation":"Der Text beginnt mit einer Binsenweisheit: Körper und Geist hängen zusammen, das ist auch wissenschaftlich anerkannt. Das „Deshalb“ tut so, als folge die Wirksamkeit der Aura-Reinigung zwangsläufig daraus. Das tut sie nicht. Dass alles verbunden ist, sagt nichts darüber, ob ein bestimmtes Verfahren eine messbare Wirkung hat. Das ist der Motte-and-Bailey-Trick: Die unstrittige „Motte“ (Körper und Geist sind verbunden) dient als Brücke zur umstrittenen „Bailey“ (meine Methode wirkt). Eine Karikatur der Gegenseite, eine Berufung auf Autoritäten oder ein falsches Entweder-oder kommen im Text nicht vor. Er arbeitet allein mit der unstrittigen Vorbehauptung und dem „Deshalb“. Eine gute Prüffrage lautet: Welchen konkreten, überprüfbaren Beleg gibt es für die Methode selbst, über den bloßen Placebo-Effekt hinaus?","coreRule":"⚡ Trenne die wahre Aussage von der Methode, die dahinter verkauft wird.","beleg":"Werkstück D.4.4 (Kontext & Tiefe, Motte-and-Bailey; Anti-Denkmuster; Werkbank-Frage)","status":"entwurf","kurz":"Der Satz über Körper und Geist ist anerkannt, doch aus ihm folgt nicht, dass eine bestimmte Methode wirkt. Das „Deshalb“ nutzt die unstrittige Aussage als Brücke zur umstrittenen Behauptung, die damit nicht belegt ist.","prueffrage":"Welche andere Behandlung ließe sich mit dem ersten Satz der Website genauso gut begründen?","rueckmeldung":[{"option":1,"text":"Eine Gegenseite taucht im Text gar nicht auf, also wird auch nichts verzerrt oder leicht widerlegt. Der Text stützt seine Methode allein auf eine Aussage, der kaum jemand widerspricht."},{"option":2,"text":"Autoritäten werden hier nicht angeführt: Der Text nennt weder Fachleute noch Institute, sondern äußert nur eine allgemein anerkannte Einsicht. Das Problem liegt im „Deshalb“, nicht in geliehenem Ansehen."},{"option":3,"text":"Ein Entweder-oder fehlt im Text. Er stellt keine zwei Wege gegenüber und lässt auch nichts Bestimmtes aus. Die Lücke liegt zwischen der unstrittigen Aussage und der Methode, die daraus abgeleitet wird."}],"familie":"rueckzug-auf-harmloses","fertigkeit":"F2"},{"id":"qx-d2-043","clusterId":"D","werkstueckRef":"D.4.4","stufe":3,"question":"Eine Bekannte erzählt dir: „Ich lasse mich jetzt nur noch ‚ganzheitlich‘ behandeln. Meine Heilerin sagt, mein Knoten in der Brust ist eine Energieblockade und braucht keine Untersuchung.“ Woran wird hier das Problem am klarsten sichtbar?","options":["Die Heilerin spricht über Energie, und schon das Wort „Energie“ macht ihr Angebot unglaubwürdig.","Aus der richtigen Idee „Körper und Geist hängen zusammen“ wird die Begründung, eine mögliche ernste Erkrankung nicht abklären zu lassen.","Die Bekannte nutzt ein alternatives Angebot, und jedes alternative Angebot ist per se gefährlich.","Die Heilerin berücksichtigt Psyche und Lebensumstände, und das allein ist schon ein Fehler."],"correctIndex":1,"explanation":"Dass Körper, Psyche und Lebensumstände zusammenhängen, ist unstrittig und gehört zur guten Medizin. Gefährlich wird „ganzheitlich“ erst dort, wo die Zustimmung zu dieser harmlosen Aussage als Freibrief dient, eine konkrete, unbewiesene Methode anzuwenden und dafür eine mögliche ernste Erkrankung nicht untersuchen oder behandeln zu lassen. Entscheidend ist die Folge: Eine nötige, wirksame Abklärung unterbleibt. Stress, Schlaf oder Entspannung anzusprechen ist dagegen unproblematisch, und ergänzende Verfahren neben der Behandlung sind es meist auch, solange die behandelnde Ärztin davon weiß.","coreRule":"⚡ Die Grenze verläuft dort, wo aus einer wahren Binsenweisheit der Verzicht auf wirksame Behandlung abgeleitet wird.","beleg":"Werkstück D.4.4 (Der Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Der Zusammenhang von Körper und Geist ist unstrittig, aber hier dient er als Begründung, einen Knoten nicht abklären zu lassen. Die Gefahr liegt nicht im Wort „ganzheitlich“, sondern darin, dass eine mögliche ernste Erkrankung ununtersucht bleibt.","prueffrage":"Was genau ändert sich für die Bekannte durch den Rat der Heilerin, verglichen mit dem, was sie sonst getan hätte?","rueckmeldung":[{"option":0,"text":"Das Wort „Energie“ wirkt esoterisch und weckt schnell Misstrauen. Problematisch wird ein Angebot aber nicht durch einzelne Begriffe, sondern durch seine Folgen: Hier unterbleibt die Untersuchung eines Knotens."},{"option":2,"text":"Vorsicht gegenüber alternativen Angeboten ist verständlich, doch „jedes“ und „per se“ gehen zu weit. Ergänzende Verfahren neben der Behandlung sind in der Regel kein Problem. Kritisch wird es, wenn dadurch eine nötige Abklärung ausfällt."},{"option":3,"text":"Wer Psyche und Lebensumstände einbezieht, macht keinen Fehler, denn Körper und Seele hängen zusammen, und gute Medizin berücksichtigt das ebenfalls. Das Problem entsteht erst, wenn daraus ein Grund wird, auf eine Untersuchung zu verzichten."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4"},{"id":"qx-d2-044","clusterId":"D","werkstueckRef":"D.4.5","stufe":1,"question":"Ein Coach sagt: „Das Gesetz der Anziehung ist so unumstößlich wie die Schwerkraft. Wenn dein Wunsch nicht eintrifft, hast du es falsch angewendet.“ Du sollst herausfinden, ob das wirklich ein Gesetz im Sinne der Naturwissenschaft ist. Welche Prüffrage deckt das Problem am besten auf?","options":["Wird das Gesetz in Büchern und Vorträgen häufig als „universell“ bezeichnet?","Welches Ergebnis würde das Gesetz eindeutig widerlegen?","Wie viele Menschen glauben an das Gesetz und wie überzeugt sind sie?","Klingt die Erklärung des Coaches in sich schlüssig und gut nachvollziehbar?"],"correctIndex":1,"explanation":"Ein Naturgesetz wie die Schwerkraft beschreibt, was beobachtbar geschieht, und ist falsifizierbar: Würde ein losgelassener Apfel zur Decke schweben, wäre das Gesetz widerlegt. Beim „Gesetz der Anziehung“ ist es umgekehrt: Es ist unfalsifizierbar. Bleibt der Wunsch unerfüllt, liegt die Schuld immer beim Anwender, nie beim „Gesetz“. Die Frage nach dem widerlegenden Ergebnis trifft genau diesen Punkt. Dass ein Gesetz häufig „universell“ genannt wird, sagt noch nichts darüber aus, ob es sich prüfen lässt. Die Zahl der Gläubigen und das selbstsichere Auftreten sagen nichts über Wahrheit aus, und eine Erklärung kann schlüssig klingen, ohne je widerlegbar zu sein.","coreRule":"⚡ Ein „Gesetz“, das nie scheitern kann, ist kein Naturgesetz: Frag, welches Ergebnis es widerlegen würde.","beleg":"Werkstück D.4.5 (Die zwei Gesetze; Kontext & Tiefe)","status":"entwurf","scenario":"Ein Coach erklärt in einem Vortrag: „Das Gesetz der Anziehung wirkt immer. Wer Reichtum aussendet, bekommt Reichtum. Wenn es bei dir nicht klappt, waren deine Gedanken nicht klar genug oder du hattest unbewusste Blockaden.“","kurz":"Ein echtes Gesetz verbietet etwas Beobachtbares: Schwebte der Apfel zur Decke, wäre die Schwerkraft widerlegt. Das „Gesetz der Anziehung“ erklärt jedes Ausbleiben zum Anwenderfehler und lässt sich deshalb nie widerlegen.","prueffrage":"Wie erklärt der Coach einen Wunsch, der eintrifft, und wie einen, der ausbleibt?","rueckmeldung":[{"option":0,"text":"Wie oft ein Gesetz „universell“ genannt wird, verrät nur, wie es beworben wird. Ob es sich an der Wirklichkeit prüfen und im Zweifel widerlegen lässt, bleibt dabei völlig offen."},{"option":2,"text":"Viele überzeugte Anhänger erklären, warum die Idee verbreitet ist, nicht, ob sie stimmt. Auch große Selbstsicherheit macht eine Behauptung nicht prüfbarer oder wahrer."},{"option":3,"text":"Schlüssig klingen kann auch eine Erklärung, die nie scheitern kann. Hier passt jedes Ergebnis ins Bild, weil Misserfolg stets dem Anwender angelastet wird. Das wirkt stimmig, macht sie aber unprüfbar."}],"familie":"widerlegung-benennen","fertigkeit":"F1"},{"id":"qx-d2-045","clusterId":"D","werkstueckRef":"D.4.5","stufe":2,"question":"Was ist an dieser Erklärung des Coaches das Problem?","scenario":"Du hast drei Monate lang jeden Morgen positiv gedacht, wie dein Coach es nach dem „Gesetz der Anziehung“ verlangt hat, und bist nicht reicher geworden. Der Coach sagt: „Das Gesetz wirkt so zuverlässig wie die Schwerkraft. Wenn sich nichts getan hat, hast du unbewusst negativ gedacht.“","options":["Jedes Ausbleiben des Erfolgs wird dem Anwender angelastet, nie der Behauptung selbst; so kann nichts sie widerlegen, und die Schuld liegt immer beim Betroffenen.","Der Coach vergleicht seine Regel mit der Schwerkraft, und das ist berechtigt: Auch die wirkt nur, wenn man sie beachtet und richtig anwendet.","Der Coach formuliert seine Behauptung zu ungenau; mit einer genaueren Formel und Messwerten wäre ihre Wirkung belegt, wie bei der Schwerkraft.","Ausbleibende Wirkung ist bei echten Naturgesetzen der Normalfall und beweist daher nichts, solange man die Regel oft genug erneut anwendet."],"correctIndex":0,"explanation":"Eine Behauptung ist nur dann prüfbar, wenn sie scheitern kann. Hier ist das ausgeschlossen: Tritt der Wunsch ein, gilt das als Beweis. Tritt er nicht ein, war angeblich der Glaube nicht stark genug oder es gab unbewusste Blockaden. Damit liegt die Schuld immer beim Anwender und nie bei der Behauptung, und kein denkbares Ergebnis könnte sie widerlegen. Bei der Schwerkraft ist das anders: Schwebte ein losgelassener Apfel zur Decke, wäre sie widerlegt, egal ob jemand daran glaubt. Wer das Scheitern grundsätzlich dem Menschen zuschreibt, schützt seine Behauptung vor jeder Kritik und beschuldigt zugleich die Betroffenen. Außerdem wertet man dann jeden Erfolg als Bestätigung und jeden Misserfolg als eigenes Versagen, was den Bestätigungsfehler verschärft.","coreRule":"⚡ Wenn nur der Anwender scheitern kann, nie die Behauptung, ist es keine Prüfung.","beleg":"Werkstück D.4.5 (Kontext & Tiefe; Der Kipppunkt; Verbindungen)","status":"entwurf","kurz":"Eine Behauptung, die kein denkbares Ergebnis widerlegen kann, sagt nichts über die Welt. Wenn Erfolg als Beweis gilt und Misserfolg als dein „unbewusst negatives“ Denken, liegt die Schuld stets bei dir und nie bei der Behauptung.","prueffrage":"Wie hätte der Coach es gedeutet, wenn du nach drei Monaten reicher geworden wärst?","rueckmeldung":[{"option":1,"text":"Der Vergleich mit der Schwerkraft klingt nach Naturgesetz, trifft aber nicht: Sie wirkt, ob man sie beachtet oder nicht, und ein zur Decke schwebender Apfel würde sie widerlegen. „Richtig anwenden“ ist hier die Hintertür für jedes Scheitern."},{"option":2,"text":"Mehr Genauigkeit und Messwerte würden die Behauptung prüfbar machen, belegen würden sie sie noch nicht. Das Problem liegt tiefer: Solange Misserfolg als Schuld des Anwenders gilt, kann auch die präziseste Formel nicht scheitern."},{"option":3,"text":"Bei echten Naturgesetzen ist ausbleibende Wirkung kein Normalfall: Die Schwerkraft wirkt jedes Mal, ein klares Gegenbeispiel würde sie widerlegen. Gilt Nicht-Wirken als normal und Wiederholen als Antwort, kann kein Ergebnis die Regel infrage stellen."}],"familie":"immunisierung-erkennen","fertigkeit":"F2"},{"id":"qx-d2-046","clusterId":"D","werkstueckRef":"D.4.5","stufe":3,"question":"Welcher Umgang mit einem solchen Gesetz entspricht dem Prinzip der Falsifizierbarkeit am besten?","options":["Die Wissenschaft hält am Gesetz fest und erklärt abweichende Messungen zu Fehlern des Beobachters, bis keine Abweichungen mehr auftreten.","Die Wissenschaft löst es durch eine genauere Theorie ab, die das Alte als Näherung miterklärt und die Abweichungen dazu.","Die Wissenschaft verwirft das Gesetz vollständig und vergisst es, weil eine widerlegte Theorie keinen Erklärwert für die Praxis behält.","Die Wissenschaft belässt das Gesetz und ändert nur seine Randbedingungen, ohne eine genauere Theorie an seine Stelle zu setzen."],"correctIndex":1,"explanation":"Ein wissenschaftliches Gesetz ist falsifizierbar: Eine Beobachtung, die ihm widerspricht, zählt als Gegenbeleg. Stößt es nachweislich an Grenzen, ist der beste Ausgang eine genauere Theorie, die alles erklärt, was das alte Gesetz erklärt hat, und dazu die Abweichungen – so löste die Relativitätstheorie Newtons Mechanik ab, die im Alltag als sehr gute Näherung weiter dient. Der Gesprächspartner übersieht diese Möglichkeit zwischen „ausnahmslos wahr“ und „wegwerfen“. Abweichungen dem Beobachter anzulasten, macht ein Gesetz dagegen unwiderlegbar. Den Geltungsbereich nur einzuengen, kann eine Übergangslösung sein, solange keine bessere Theorie bekannt ist, erklärt die Abweichungen aber nicht.","coreRule":"⚡ Ein echtes Gesetz darf scheitern und wird dann durch eine genauere Theorie ersetzt. Wer Misserfolge stets dem Anwender oder neuen Ausnahmen zuschreibt, schützt einen Glaubenssatz.","beleg":"Werkstück D.4.5 (Kontext & Tiefe, „Ein wissenschaftliches Gesetz“; Verweis A.20)","status":"entwurf","scenario":"Ein Gesprächspartner sagt: „Ein Gesetz, das irgendwo nachweislich danebenliegt, ist wertlos. Entweder es stimmt ausnahmslos, oder man kann es wegwerfen.“ Du sollst beurteilen, wie die Wissenschaft mit einem Gesetz umgeht, das nachweislich an Grenzen stößt – etwa Newtons Mechanik bei sehr hohen Geschwindigkeiten.","kurz":"Ein Gesetz, das an Grenzen stößt, ist falsifiziert, aber nicht wertlos: Eine genauere Theorie löst es ab und erklärt das Alte mit, dazu die Abweichungen. Der Fehler liegt in der Annahme, es gebe nur „ausnahmslos wahr“ oder „wegwerfen“.","prueffrage":"Gilt Newtons Mechanik im Alltag weiterhin zuverlässig, und wo genau beginnen die Abweichungen?","rueckmeldung":[{"option":0,"text":"Messfehler gibt es wirklich, und ein bewährtes Gesetz kippt nicht beim ersten Ausreißer. Wiederholte, nachgewiesene Abweichungen aber dem Beobachter anzulasten, macht ein Gesetz unwiderlegbar und damit unwissenschaftlich."},{"option":2,"text":"Als allgemeingültiges Gesetz ist es tatsächlich widerlegt. Aber vergessen wird es nicht: Im bewährten Bereich bleibt es brauchbar, und die neue Theorie erklärt, warum es dort funktioniert. Genau diese Möglichkeit übersieht auch der Gesprächspartner."},{"option":3,"text":"Die Grenzen eines Gesetzes zu benennen und seinen Geltungsbereich einzuengen, gehört dazu. Wenn dann aber keine genauere Theorie die Abweichungen erklärt, bleibt der Gegenbeleg unverstanden, und das Gesetz wird nur notdürftig gerettet."}],"familie":"immunisierung-erkennen","fertigkeit":"F2"},{"id":"qx-d2-047","clusterId":"D","werkstueckRef":"D.4.5","stufe":4,"question":"Der Heilpraktiker sagt: „Meine Methode folgt fünf biologischen Naturgesetzen. Wenn eine Behandlung nicht anschlägt, haben Patienten das Gesetz nicht richtig befolgt.“ Was ist an dieser Rechtfertigung am problematischsten?","options":["Das Wort „Naturgesetz“ leiht der Methode die Autorität echter Gesetze, obwohl sie weder prüfbar noch widerlegbar ist.","Die Zahl von nur fünf Gesetzen ist zu klein, um eine Methode gründlich zu begründen oder abzusichern.","Für ärztliche Behandlungen zählen allein Erfahrungswerte aus der Praxis, Gesetze der Biologie spielen keine Rolle.","Die Methode verlangt von den Patienten zu viel Mitarbeit, eine gute Methode wirkt auch bei halber Befolgung."],"correctIndex":0,"explanation":"Ein echtes Naturgesetz beschreibt, was geschieht, macht überprüfbare Vorhersagen und wäre durch ein gegenteiliges Ergebnis widerlegt. Die Methode des Heilpraktikers erfüllt nichts davon: Er nennt keine Prüfung, und jedes Scheitern wird dem Patienten angelastet, sodass nichts sie je widerlegen könnte. Das Wort „Naturgesetz“ erzeugt hier nur den Anschein von Notwendigkeit und Wissenschaftlichkeit. Ein Anspruch dieser Art muss sich an denselben Maßstäben messen lassen wie ein echtes Gesetz: Was sagt er voraus, und was würde ihn widerlegen?","coreRule":"⚡ Wer „Naturgesetz“ sagt, muss Vorhersage und Widerlegbarkeit liefern.","beleg":"Werkstück D.4.5 (Anwendung & Relevanz, „In der Pseudomedizin“; Kernidee)","status":"entwurf","scenario":"Ein Heilpraktiker wirbt für ein Therapiekonzept, das er nie in Studien geprüft hat. Auf Nachfrage verweist er auf „fünf biologische Naturgesetze“. Ein Patient, dem die Behandlung nicht geholfen hat, soll laut ihm selbst schuld sein.","kurz":"Das Wort „Naturgesetz“ verleiht der Methode den Anschein von Notwendigkeit, doch ein echtes Gesetz sagt Prüfbares voraus und wäre widerlegbar. Hier wird jedes Scheitern dem Patienten angelastet, sodass nichts die Methode je widerlegen könnte.","prueffrage":"Welche Prüfung seiner Methode nennt der Heilpraktiker, und wie erklärt er den Fall eines Patienten, dem sie nicht geholfen hat?","rueckmeldung":[{"option":1,"text":"Eine kleine Zahl sieht nach dünner Grundlage aus, aber Menge sagt wenig über Qualität. Auch fünfzig Gesetze wären wertlos, wenn sie nichts Prüfbares vorhersagen und kein Ergebnis sie widerlegen könnte."},{"option":2,"text":"Praxiserfahrung zählt in der Medizin durchaus, doch sie allein täuscht leicht, etwa weil Beschwerden oft von selbst abklingen. Deshalb braucht es systematische Prüfung, und biologische Gesetzmäßigkeiten gehören selbstverständlich dazu."},{"option":3,"text":"Die Schuld beim Patienten zu suchen, fällt sofort auf. Ob die Methode viel Mitarbeit verlangt, ist aber unbekannt, und manche wirksame Behandlung hilft nur bei voller Befolgung. Schwerer wiegt: Die Ausrede erklärt jedes Scheitern weg."}],"familie":"widerlegung-benennen","fertigkeit":"F1"}]`);export{t as n,n as t};